// NEW3 — Exam 3 items in her formats the bank lacked: NOT/EXCEPT, true/false, which pairing is wrong,
// patient scenarios for the poisoning table, fill in the blank. Each item carries its own lecture and sub.
// Generated from scratchpad new3/gen.py; quotes checked verbatim against the transcripts.
QUESTIONS.push(
{"id": "NEW3-001", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "princ", "skill": "recall", "concept": "not-five-principles", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her Quiz 1 question 10: list the five principles of toxicology", "stem": "Which of the following is NOT one of the five principles of toxicology?", "options": [{"t": "Source", "correct": false, "why": "Source is the first principle: where the toxin or toxicant comes from."}, {"t": "Dose", "correct": false, "why": "Dose is the fourth principle: \"Dose makes the poison.\""}, {"t": "ADMET", "correct": false, "why": "ADMET (absorption, distribution, metabolism, excretion, toxicity) is the third principle."}, {"t": "Tolerance", "correct": true, "why": "Tolerance, decreased responsiveness after prior exposure, is one of the general concepts of undesired effects (Toxic Responses deck). It is not one of the five principles."}], "teach": "The five principles, as her Quiz 1 keyed them: 1. Source 2. Exposure 3. ADMET 4. Dose 5. Target and Mechanism of Action. Tolerance is taught later with the general concepts of undesired effects, where it has two mechanisms: dispositional tolerance and reduced responsiveness.", "quote": "Toxicologists think of these five principles. We think about the source of a toxin or toxicant. We think about how are people or critters exposed.", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘5 Principles of Toxicology’; Smith_Practice_Quiz_1_-_Principles_of_Toxicology.pdf question 10; transcript 10/9"},
{"id": "NEW3-002", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "shape", "skill": "recall", "concept": "not-dose-response-statements", "tags": ["smith", "not"], "source": "both", "stem": "Which statement about dose and the dose–response relationship is NOT correct?", "options": [{"t": "\"The dose makes the poison\" is attributed to Paracelsus", "correct": false, "why": "Correct statement: she attributed the phrase to Paracelsus."}, {"t": "The LD50 is the dose that kills 50% of the animals given it", "correct": false, "why": "Correct statement: the LD50 is read where the cumulative mortality curve crosses 50%."}, {"t": "Carcinogens have been modeled with a linear, no-threshold curve", "correct": false, "why": "Correct statement: \"this is what we thought was going on with carcinogens for the longest time ... that they were totally linear in their dose response.\""}, {"t": "Each compound has a dose below which it causes no harm", "correct": true, "why": "Not correct. Some dose–response curves have a threshold and some (the linear model used for carcinogens) do not: \"don't always assume everything has an area where a dose is not harmful.\""}], "teach": "A threshold dose is the dose below which no response is seen. She showed two illustrations: a sigmoidal curve with a threshold, and a straight line from zero with no threshold, the model long used for carcinogens, where one molecule might start the damage. Paracelsus is credited with \"the dose makes the poison\"; the LD50 comes from a population dose–response curve.", "quote": "So don't always assume everything has an area where a dose is not harmful. Not everything is like this.", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slides ‘Dose’, ‘Threshold Dose’, ‘More on Threshold Dose’; transcript 10/9"},
{"id": "NEW3-003", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "general", "skill": "recall", "concept": "not-reversibility", "tags": ["smith", "not"], "source": "both", "stem": "Which statement about the reversibility of toxic effects is NOT correct?", "options": [{"t": "A tissue's ability to regenerate determines reversibility", "correct": false, "why": "Correct statement, from the slide: \"Ability of tissue to regenerate determines reversibility or irreversibility.\""}, {"t": "The liver has a high ability to regenerate", "correct": false, "why": "Correct statement: the liver has a high ability to regenerate, so most liver injuries are reversible."}, {"t": "Cancer and birth defects are considered irreversible", "correct": false, "why": "Correct statement, from the slide: \"Cancer and birth defects - considered irreversible toxic effects.\""}, {"t": "Most injuries to the central nervous system are reversible", "correct": true, "why": "Not correct. Differentiated cells of the CNS cannot divide and be replaced, so most CNS injuries are irreversible."}], "teach": "Reversible vs irreversible: the ability of a tissue to regenerate decides it. Liver: high ability to regenerate, most injuries reversible. CNS: differentiated cells cannot divide and be replaced, most injuries irreversible. Cancer and birth defects are considered irreversible. One exposure can give both: \"So sometimes you get both.\"", "quote": "most of our ... nerves or CNS cells ... their injury is permanent. They can't divide. They can't be regenerated.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Undesired Effects: general concepts Reversible vs. Irreversible’; transcript 10/13"},
{"id": "NEW3-004", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "ontarget", "skill": "tell", "concept": "not-on-target-cause", "tags": ["smith", "not"], "source": "slide", "stem": "All of the following are on-target causes of an adverse drug effect EXCEPT:", "options": [{"t": "The dose at the receptor is too high", "correct": false, "why": "On-target: the first example on the On-Target Examples slide (deliberate or accidental dosing errors, changes in pharmacokinetics, a change in receptor number)."}, {"t": "A change in the drug's pharmacokinetics", "correct": false, "why": "On-target: changes in pharmacokinetics raise the dose at the intended receptor."}, {"t": "A change in the number of receptors", "correct": false, "why": "On-target: a change in receptor number is listed under the dose at the receptor being too high."}, {"t": "An enantiomer hits an unintended receptor", "correct": true, "why": "Off-target. On the Off-Target Examples slide this is teratogenesis with racemic thalidomide: the S-enantiomer is a potent teratogen."}], "teach": "On-target examples: the dose at the receptor is too high (dosing errors, changes in pharmacokinetics, change in receptor number), and the drug acts at the correct receptor in the wrong tissue (sleepiness with diphenhydramine). Off-target examples: the drug hits an unintended receptor (terfenadine and the cardiac potassium channel), an enantiomer hits an unintended receptor (thalidomide), and activation of unintended receptor subtypes (propranolol and beta-2 receptors in the airway).", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slides ‘Toxic Endpoints On-Target Examples’, ‘Toxic Endpoints Off-Target Examples’"},
{"id": "NEW3-005", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "nonorgan", "skill": "tell", "concept": "not-nonorgan-specific", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Objective slide; her Quiz 2 question 2 and Poll Everywhere question (10/14)", "stem": "Which toxic response is NOT considered non-organ specific?", "options": [{"t": "Fibrosis", "correct": false, "why": "Non-organ specific: the same collagen and extracellular matrix pathology in the lung or the liver."}, {"t": "Cancer", "correct": false, "why": "Non-organ specific: the same cellular mechanism can cause cancers in different organs."}, {"t": "Teratogenesis", "correct": false, "why": "Non-organ specific: the defect depends on the time of exposure during gestation."}, {"t": "Hepatotoxicity", "correct": true, "why": "Hepatotoxicity is an organ-specific response (the liver), along with pulmonary toxicity, neurotoxicity and nephrotoxicity."}], "teach": "The objective slide names four non-organ-specific responses: fibrosis, genotoxicity, cancer and teratogenesis. The organ-specific ones are pulmonary toxicity, neurotoxicity, hepatotoxicity and nephrotoxicity. Fibrosis is non-organ specific because the fibrotic tissue has the same chemistry wherever it forms.", "quote": "if you look at the chemistry of that fibrotic tissue, it's the same. So the same pathology goes on to create that fibrosis.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slides ‘Outline and Objectives’, ‘Toxic Endpoints Non-Organ Specific: Fibrosis’; transcript 10/13"},
{"id": "NEW3-006", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "hepat", "skill": "recall", "concept": "not-liver-susceptible", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her Poll Everywhere question 3 (10/14) and the slide's list", "stem": "The liver is susceptible to toxicity for all of the following reasons EXCEPT:", "options": [{"t": "It takes up and concentrates compounds", "correct": false, "why": "A reason: it can take up and concentrate compounds in its cells."}, {"t": "Its metabolism may bioactivate compounds", "correct": false, "why": "A reason: it does a lot of metabolism, which may bioactivate compounds to toxic metabolites."}, {"t": "It has its own inflammatory cells", "correct": false, "why": "A reason: its Kupffer cells release inflammatory compounds and reactive oxygen species while cleaning up."}, {"t": "It is a large organ", "correct": true, "why": "Not a reason. On her poll she said its size \"really doesn't have anything to do with it.\""}], "teach": "Why the liver is susceptible: it takes up and concentrates compounds in its cells; it does a lot of metabolism, which may bioactivate compounds; it has its own inflammatory cells (Kupffer cells); it tends to have idiosyncratic reactions. Her poll added that it receives a large volume of blood through the portal circulation. Its size is not a reason.", "quote": "It's a large organ ... that really doesn't have anything to do with it", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Hepatotoxicity – Why is liver susceptible?’ and PollEV ‘The liver is very susceptible to drug toxicity because…’; transcript 10/14"},
{"id": "NEW3-007", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "pulm", "skill": "tell", "concept": "not-chronic-pulmonary", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her words 10/14: for pulmonary toxicity, think acute versus chronic responses", "stem": "Which pulmonary response is NOT a chronic response to an exposure?", "options": [{"t": "Fibrosis", "correct": false, "why": "Chronic: an increase in collagen that reduces the lung's plasticity."}, {"t": "Emphysema", "correct": false, "why": "Chronic: lungs become larger and too plastic, with hyperinflation."}, {"t": "Asthma", "correct": false, "why": "Chronic: she said asthma is considered a chronic response to pulmonary exposures."}, {"t": "Pulmonary edema", "correct": true, "why": "Acute: the acute exudative phase that thickens the alveolar-capillary barrier. Airway reactivity is the other acute response."}], "teach": "Acute pulmonary responses: airway reactivity (bronchoconstriction, decreased airway diameter) and pulmonary edema. Chronic responses: fibrosis, emphysema and asthma.", "quote": "so air reactivity and pulmonary edema are acute responses to inhaling things that are bad for our lungs. Some of our chronic responses would be fibrosis ... emphysema, and then asthma is considered a chronic response to pulmonary exposures", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Types of Pulmonary Toxicity’; transcript 10/14"},
{"id": "NEW3-008", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "neuro", "skill": "recall", "concept": "not-bbb-statements", "tags": ["smith", "not"], "source": "both", "stem": "Which statement about the blood–brain barrier is NOT correct?", "options": [{"t": "Penetration depends on a compound's lipophilicity", "correct": false, "why": "Correct statement, from the slide."}, {"t": "Transporters move some compounds back to the blood", "correct": false, "why": "Correct statement, from the slide."}, {"t": "It is still developing at birth", "correct": false, "why": "Correct statement: still developing at birth, for several months to years."}, {"t": "It is continuous throughout the brain", "correct": true, "why": "Not correct. The slide says it \"Is not continuous\": in some parts of the brain it is looser than in others."}], "teach": "Blood–brain barrier, from the Neurotoxicity slide: compounds must pass into endothelial cell membranes; transporters move some compounds back to the blood; penetration depends on lipophilicity; it is not continuous; it is still developing at birth, so a medication that is safe in an adult may reach a newborn's brain.", "quote": "There are parts of the brain where the blood-brain barrier is like, I guess you'd say looser than others. And then another thing to think about is that when children are born. That blood-brain barrier is still developing at birth for several months to years.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Neurotoxicity’; transcript 10/14"},
{"id": "NEW3-009", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "nephro", "skill": "tell", "concept": "not-renal-failure-mechanism", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her words 10/14: know these different kinds of renal damage", "stem": "Which is NOT one of the mechanisms of chemically induced acute renal failure?", "options": [{"t": "Crystalluria", "correct": false, "why": "A renal mechanism on the table (for example sulfonamides, acyclovir, ethylene glycol)."}, {"t": "Interstitial nephritis", "correct": false, "why": "A renal mechanism on the table; she added the PPIs to its list."}, {"t": "Glomerulopathy", "correct": false, "why": "A renal mechanism on the table (for example gold, penicillamine, NSAIDs)."}, {"t": "Steatosis", "correct": true, "why": "Steatosis (fatty liver) is one of the kinds of liver response, not a mechanism of renal failure."}], "teach": "Mechanisms of chemically induced acute renal failure on the table: prerenal, vasoconstriction, crystalluria, tubular toxicity, endothelial injury, glomerulopathy and interstitial nephritis. She said to know these kinds of renal damage, not the drug lists. Steatosis belongs to the table of liver responses.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Site-Specific Nephrotoxicity’ (Klaassen Table 14-2); transcript 10/14"},
{"id": "NEW3-010", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "odkin", "skill": "recall", "concept": "not-kinetics-in-overdose", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her Quiz 3 question 6: overdose does affect a drug's kinetics", "stem": "Which statement about pharmacokinetics in overdose is NOT correct?", "options": [{"t": "Exceeding protein-binding capacity raises the free fraction", "correct": false, "why": "Correct statement: an overdose may exceed protein-binding capacity, raising the fraction of free drug."}, {"t": "Saturated liver metabolism reduces the first-pass effect", "correct": false, "why": "Correct statement: more drug reaches the circulation."}, {"t": "Elimination may change from first order to zero order", "correct": false, "why": "Correct statement: high plasma concentrations may change elimination to zero order, extending the half-life."}, {"t": "A drug with a large Vd is easy to remove by hemodialysis", "correct": true, "why": "Not correct. Overdosed drugs with a large volume of distribution are hard to remove from the blood: most of the drug is not in the vasculature."}], "teach": "Kinetics can change in overdose. Large Vd (over 5 L/kg): hard to remove from blood by hemodialysis. Absorption: slowed tablet dissolution or gastric emptying delays peak effects; injury to the gut can increase absorption. Saturated liver metabolism lowers first-pass effect. Protein binding may be exceeded, raising free drug. First-order elimination may become zero order, extending the half-life.", "quote": "Why would drugs with very large volumes of distribution be very challenging to remove by hemodialysis? What does that large volume of distribution mean when we think about where the drug went in the body ... it's not staying in the vasculature", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘How Pharmacokinetics change in Overdose’; transcript 10/14"},
{"id": "NEW3-011", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "approach", "skill": "tell", "concept": "not-toxicokinetic-method", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Objective slide: list the four categories of toxicokinetic-based treatment; her Quiz 3 questions 1 and 9", "stem": "Which is NOT one of the four toxicokinetic-based methods of treating a poisoning?", "options": [{"t": "Prevention of absorption", "correct": false, "why": "One of the four toxicokinetic methods."}, {"t": "Inhibition of bioactivation", "correct": false, "why": "One of the four toxicokinetic methods (inhibition of toxication)."}, {"t": "Enhancement of elimination", "correct": false, "why": "One of the four toxicokinetic methods."}, {"t": "Inactivation of the poison", "correct": true, "why": "Inactivation is its own approach, the second of the three basic approaches, not a toxicokinetic method."}], "teach": "Three basic approaches: toxicokinetic based, inactivation of poison, pharmacologically based. The four toxicokinetic methods: prevention of absorption, inhibition of toxication (bioactivation), enhancement of metabolism (detoxification), enhancement of elimination.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slides ‘General principles for treating the poisoned patient’, ‘Toxicokinetic-Based Treatment’; transcript 10/14"},
{"id": "NEW3-012", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "inact", "skill": "recall", "concept": "except-chelator-traits", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her Quiz 3 question 10 format: an inactivator's characteristics EXCEPT", "stem": "A heavy metal chelator should have all of the following characteristics EXCEPT:", "options": [{"t": "Higher affinity for the metal than for tissue macromolecules", "correct": false, "why": "Required: the slide says it \"Must have higher affinity for binding metal than tissue macromolecules.\""}, {"t": "Water solubility, low toxicity and ready clearance", "correct": false, "why": "Required: \"Must be water soluble and non-toxic, and readily cleared.\""}, {"t": "Low binding affinity for endogenous ions such as calcium", "correct": false, "why": "Required: \"Ideal chelator has low binding affinities for endogenous ions such as calcium.\""}, {"t": "A single binding site for one metal atom", "correct": true, "why": "Not a characteristic. Chelators are multidentate: one molecule binds a single metal atom at several sites."}], "teach": "Heavy metal chelators bind lead, mercury, cadmium, iron and copper. They are small molecules with a nucleophilic electron donor that forms a metal-ligand complex, usually multidentate. They must bind the metal with higher affinity than tissue macromolecules, be water soluble, non-toxic and readily cleared, and ideally have low affinity for endogenous ions such as calcium.", "quote": "It has a multidentate structure, usually is what our chelators have ... the chelating agent must have a higher affinity for binding the toxic metal than macromolecules naturally in your body.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Inactivation of Poisons: Heavy Metal Chelators’; transcript 10/19"},
{"id": "NEW3-013", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "pharmrec", "skill": "tell", "concept": "not-pharmacological-category", "tags": ["smith", "not"], "source": "both", "stem": "Which is NOT one of the four categories of pharmacologically based treatment?", "options": [{"t": "The treatment is a receptor antagonist", "correct": false, "why": "One of the four categories (naloxone, flumazenil, atropine)."}, {"t": "The treatment is a receptor agonist", "correct": false, "why": "One of the four categories (physostigmine)."}, {"t": "The treatment by-passes an inhibited pathway", "correct": false, "why": "One of the four categories (vitamin K for warfarin)."}, {"t": "The treatment supplies a cofactor for metabolism", "correct": true, "why": "Supplying a cofactor is enhancement of metabolism, a toxicokinetic method (thiosulfate for cyanide, NAC for acetaminophen)."}], "teach": "The four pharmacologically mediated treatments: the treatment is a receptor antagonist; the treatment is a receptor agonist; the treatment removes the poison from the active site; the treatment by-passes an inhibited pathway. Giving a cofactor to speed a reaction is the toxicokinetic method of enhancing metabolism.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Pharmacological Treatment’; transcript 10/19"},
{"id": "NEW3-014", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "renal", "skill": "recall", "concept": "not-ion-trapping", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her Quiz 3 question 9: renal clearance can be enhanced by ion trapping", "stem": "Which statement about enhancing renal elimination by ion trapping is NOT correct?", "options": [{"t": "Sodium bicarbonate enhances clearance of a weakly acidic toxin", "correct": false, "why": "Correct statement, from the slide."}, {"t": "It is very effective for salicylates and phenobarbital", "correct": false, "why": "Correct statement, from the slide."}, {"t": "It prevents tubular reabsorption of the toxin", "correct": false, "why": "Correct statement: the charged toxin stays in the urine."}, {"t": "It is routinely done for toxins that are weakly basic", "correct": true, "why": "Not correct. The slide says it is \"Not done for toxins that are weakly basic\": acidifying a person's blood to acidify the urine is dangerous."}], "teach": "Enhance renal elimination: a common way to treat acute poisonings. Ion trapping prevents tubular reabsorption: sodium bicarbonate raises urine pH, a weakly acidic toxin becomes charged and is not reabsorbed. Very effective for salicylates and phenobarbital. Not done for weakly basic toxins.", "quote": "we don't tend to do this for poisons that are weakly basic, because acidifying a person's blood to try to get their urine more acidic is kind of dangerous", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Toxicokinetic-Based Treatment Enhance Renal Elimination’; transcript 10/19"},
{"id": "NEW3-015", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "recall", "concept": "not-bb-symptom", "tags": ["smith", "not"], "source": "slide", "core": true, "coreWhy": "Her key's symptom column; her Quiz 3 question 5 format", "stem": "Choose the symptom that is NOT part of beta-blocker overdose:", "options": [{"t": "Hypotension", "correct": false, "why": "Listed for beta-blocker overdose."}, {"t": "Bradycardia", "correct": false, "why": "Listed for beta-blocker overdose."}, {"t": "Respiratory depression", "correct": false, "why": "Listed for beta-blocker overdose."}, {"t": "Tachycardia", "correct": true, "why": "Not listed. Beta-blocker overdose slows the heart (bradycardia); tachycardia is listed for tricyclic antidepressant overdose and for iron."}], "teach": "Beta blockers row of her key: hypotension, bradycardia, altered mental status, respiratory depression. The altered mental status separates it from calcium channel blocker overdose (hypotension, bradycardia, but often alert).", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’"},
{"id": "NEW3-016", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "recall", "concept": "not-tca-symptom", "tags": ["smith", "not"], "source": "slide", "core": true, "coreWhy": "Her key's symptom column; her Quiz 3 question 5 format", "stem": "Choose the finding that is NOT part of tricyclic antidepressant overdose:", "options": [{"t": "Dilated pupils", "correct": false, "why": "Listed for tricyclic antidepressant overdose."}, {"t": "Elongated QRS interval", "correct": false, "why": "Listed; sodium bicarbonate is given for it."}, {"t": "Dry mouth", "correct": false, "why": "Listed for tricyclic antidepressant overdose."}, {"t": "Elevated serum potassium", "correct": true, "why": "Not listed here. Elevated serum potassium is in the digoxin row."}], "teach": "Tricyclic antidepressants row of her key: tachycardia, dilated pupils, dry mouth, agitation, seizures, sometimes vasodilation, elongated QRS interval, reduced cardiac contractility. Treatments: intravenous fluids, dopamine or norepinephrine, sodium bicarbonate for the elongated QRS.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Tricyclic Antidepressants’"},
{"id": "NEW3-017", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "recall", "concept": "not-special-considerations", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her key's special considerations column", "stem": "Which statement about the special considerations for antidotes is NOT correct?", "options": [{"t": "N-acetylcysteine loses effectiveness about 8 hours after overdose", "correct": false, "why": "Correct statement, from the acetaminophen row; it should still be given past that point."}, {"t": "Fomepizole has fewer adverse effects than ethanol", "correct": false, "why": "Correct statement: fomepizole is the stronger alcohol dehydrogenase inhibitor with fewer adverse effects."}, {"t": "Naloxone can trigger withdrawal in chronic opioid users", "correct": false, "why": "Correct statement, from the opioids row."}, {"t": "Serum digoxin levels guide further Fab doses after the antidote", "correct": true, "why": "Not correct. Total digoxin (free and bound to Fab) increases, so the measurement can't be used to calculate more Fab doses."}], "teach": "Special considerations in her key: acetaminophen, NAC loses effectiveness about 8 hours after overdose but is still given; toxic alcohols, fomepizole is a stronger alcohol dehydrogenase inhibitor with fewer adverse effects than ethanol; benzodiazepines, flumazenil can cause withdrawal in a dependent patient; beta blocker vs calcium channel blocker, BB OD may have altered mental status; digoxin, total digoxin rises after Fab so levels can't guide more doses; opioids, naloxone can trigger withdrawal.", "cite": "PoisoningTreatmentTable2026KEY.pdf special considerations column; transcript 10/20"},
{"id": "NEW3-018", "lecture": "L17", "prof": "Smith", "tier": "new", "topic": "L17", "sub": "genophen", "skill": "tell", "concept": "not-genotype-phenotype-complication", "tags": ["smith", "not"], "source": "both", "stem": "Which of the following does NOT complicate the relationship between genotype and phenotype?", "options": [{"t": "Many polymorphisms may be present in a single gene", "correct": false, "why": "A complication listed on the slide: it is hard to tell which variation causes the phenotype."}, {"t": "Most traits are multigenic, not monogenic", "correct": false, "why": "A complication listed on the slide."}, {"t": "Environmental factors may influence the trait", "correct": false, "why": "A complication listed on the slide (gene-environment interactions)."}, {"t": "Each person carries two alleles of each gene", "correct": true, "why": "True, but not a complication: it is the definition of a genotype, the two alleles a person has."}], "teach": "Complications of genotype vs phenotype: many polymorphisms may be present in a single gene; most traits are multigenic, not monogenic; traits may be influenced by environmental factors (gene-environment interactions). A genotype is the two alleles a person carries for a gene; a phenotype is any observable characteristic.", "quote": "Most traits are multigenic, not monogenic.", "cite": "Intro_to_PGx_Lecture_Students_Fall_2026.pdf slides ‘Genotype vs phenotype’ (p. 17), ‘Complications of Genotype vs phenotype’ (p. 18); transcript 10/20"},
{"id": "NEW3-019", "lecture": "GRG3", "prof": "Smith", "tier": "new", "topic": "GRG3", "sub": "both", "skill": "recall", "concept": "not-out-of-hospital-steps", "tags": ["smith", "not"], "source": "both", "core": true, "coreWhy": "Her key (guideline reading guide) and her words 10/19: know you don't make them vomit at home", "stem": "For a beta-blocker or calcium channel blocker overdose found at home, which statement is NOT correct?", "options": [{"t": "Consider activated charcoal if there are no contraindications", "correct": false, "why": "Correct statement, from question 1 of the key for both classes."}, {"t": "A patient who is symptomatic when found goes to a hospital", "correct": false, "why": "Correct statement: \"Get them to a hospital.\""}, {"t": "A patient who needs the hospital is brought by ambulance", "correct": false, "why": "Correct statement, from question 3 of the key."}, {"t": "Induce emesis at home before transport to the hospital", "correct": true, "why": "Not correct. The key says \"Do not induce emesis\"; she said it is too dangerous."}], "teach": "Both columns of her key: do not induce emesis; consider activated charcoal if there are no contraindications; do not delay transport to the hospital to administer charcoal. A symptomatic patient goes to a hospital, by ambulance. On 10/19: \"you need to know you don't make them barf at home, it's too dangerous.\"", "quote": "you don't make them barf at home, it's too dangerous", "cite": "Readingguideforoutofhospitalguidelines2026KEY.docx, questions 1, 2 and 3, both columns; transcript 10/19"},
{"id": "NEW3-020", "lecture": "RMK3", "prof": "Smith", "tier": "new", "topic": "RMK3", "sub": "exposure", "skill": "recall", "concept": "not-human-route", "tags": ["smith", "not"], "source": "slide", "stem": "Which route of exposure to pharmaceuticals in water is NOT listed for humans?", "options": [{"t": "Ingestion of drinking water", "correct": false, "why": "Listed for humans."}, {"t": "Ingestion of fish", "correct": false, "why": "Listed for humans."}, {"t": "Recreational dermal exposure", "correct": false, "why": "Listed for humans."}, {"t": "Inhalation", "correct": true, "why": "Not listed for humans. The key's routes for humans are ingestion of drinking water, ingestion of fish and recreational dermal exposure."}], "teach": "Exposure row, routes. Humans: ingestion of drinking water, ingestion of fish, recreational dermal exposure. Aquatic wildlife: ingestion of drinking water, ingestion of food, dermal. Aquatic wildlife exposure is the more significant.", "cite": "KeyDiscussionGuideRodriguez-MozazandWeinberg2026.docx, row Exposure, Route"},
{"id": "NEW3-021", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "admet", "skill": "recall", "concept": "tf-detoxification", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Detoxification is metabolism of a compound to something less harmful and better able to be eliminated from the body.", "options": [{"t": "True", "correct": true, "why": "Her definition of detoxification, the opposite of bioactivation."}, {"t": "False", "correct": false, "why": "The statement is her definition. Metabolism that makes a compound more harmful is bioactivation."}], "teach": "Two outcomes of metabolism: bioactivation (toxication; something more harmful than the parent, e.g. acetaminophen to NAPQI by CYP2E1) and detoxification (something less harmful and easier to eliminate, e.g. acetaminophen conjugated by the glucuronosyl transferases and sulfotransferases).", "quote": "we'll use the word detoxification ... that's metabolism to something that's less nasty, something better able to be eliminated from the body", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slides ‘ADME: Metabolism’, ‘Example of Bioactivation’; transcript 10/9"},
{"id": "NEW3-022", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "admet", "skill": "recall", "concept": "tf-metabolism-always-safer", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Metabolism always makes a compound less toxic.", "options": [{"t": "True", "correct": false, "why": "Not true: metabolism can create something more harmful than the parent compound."}, {"t": "False", "correct": true, "why": "False. Bioactivation is metabolism to something more harmful, such as acetaminophen to NAPQI."}], "teach": "Toxicologists watch metabolism because a compound \"might be metabolized to something even nastier\". That is bioactivation (also called toxication or metabolic activation). Acetaminophen is her classic example: CYP2E1 makes NAPQI, which is toxic to the liver.", "quote": "is the metabolism part where a compound might be metabolized to something even nastier ... I use the word bioactivation for that.", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slides ‘ADME: Metabolism’, ‘Example of Bioactivation’; transcript 10/9"},
{"id": "NEW3-023", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "freq", "skill": "apply", "concept": "tf-below-toxic-never-harm", "tags": ["smith", "tf"], "source": "both", "core": true, "coreWhy": "Her Quiz 1 question 1 (a compound cleared before the next exposure may still cause adverse effects)", "stem": "True or False: A compound that never reaches a toxic blood concentration with repeated dosing can never cause an adverse response.", "options": [{"t": "True", "correct": false, "why": "Not true: it can still cause an adverse response."}, {"t": "False", "correct": true, "why": "False. For compound C she accepted an allergic reaction, an action at a different target site, and synergy with other drugs as ways it could still cause a bad response."}], "teach": "In the repeated-dose figure, compound C is cleared between doses and never reaches the toxic zone. She asked whether C could still cause a bad response and accepted: an allergy to it, toxicity at a different target site, and synergy with other drugs. Her Quiz 1 question 1 made the related point that a compound cleared before the next exposure may still have chronic adverse effects.", "quote": "Could you still have a bad response to it? ... you could be allergic to it ... Might be going to a different target site ... Could synergize with other drugs", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘Exposure: Frequency’ (Casarett & Doull Fig 2-4); transcript 10/9"},
{"id": "NEW3-024", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "general", "skill": "recall", "concept": "tf-local-or-systemic-never-both", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: A poison can cause a local effect or a systemic effect, but never both.", "options": [{"t": "True", "correct": false, "why": "Not true: some poisons have both local and systemic effects."}, {"t": "False", "correct": true, "why": "False. The slide's example of a poison with both is tetraethyl lead."}], "teach": "Local effects occur at the site of first contact (chlorine gas). Systemic effects require absorption and distribution; most toxins cause systemic effects unless highly reactive. Some poisons have both (tetraethyl lead). Some cause indirect systemic effects (acid burns).", "quote": "Weirdly, some compounds do have both local and systemic effects, very few. I like to give the example of tetraethyl lead.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Undesired Effects: general concepts Local vs. Systemic’; transcript 10/13"},
{"id": "NEW3-025", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "general", "skill": "recall", "concept": "tf-cancer-birth-defects-irreversible", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Cancer and birth defects are considered irreversible toxic effects.", "options": [{"t": "True", "correct": true, "why": "True, from the Reversible vs. Irreversible slide."}, {"t": "False", "correct": false, "why": "The statement is the slide's: \"Cancer and birth defects - considered irreversible toxic effects.\""}], "teach": "Even when a cancer is treated by surgery, radiation or chemotherapy, the cancerous tissue is not returned to normal, so cancer is counted as irreversible; a malformed body part in a fetus cannot be fixed either.", "quote": "cancer and birth defects are also considered to be obviously an undesired effect with certain exposures, and those are considered irreversible as well.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Undesired Effects: general concepts Reversible vs. Irreversible’; transcript 10/13"},
{"id": "NEW3-026", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "nonorgan", "skill": "tell", "concept": "tf-mutagenicity-transmissible", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Mutagenicity refers to genetic alterations that are transmissible, so they can be passed down to offspring.", "options": [{"t": "True", "correct": true, "why": "True: mutagenicity is transmissible; genotoxicity is DNA damage in general."}, {"t": "False", "correct": false, "why": "The statement matches the slide: \"Mutagenicity: Transmissible genetic alterations.\""}], "teach": "Genotoxicity is damage to DNA in general and can occur in somatic or germ cells; the slide says it is not transmissible. Mutagenicity is a transmissible genetic alteration; mutations in germ cells make the agent a mutagen. Results of genotoxicity: cancer, teratogenesis, genetically based disorders.", "quote": "And mutagenicity refers to the fact that it's transmissible. In other words, you can pass that down to your offspring", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Non-Organ Specific: Genotoxicity’; transcript 10/13"},
{"id": "NEW3-027", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "nonorgan", "skill": "tell", "concept": "tf-teratogen-same-defect-any-time", "tags": ["smith", "tf"], "source": "both", "core": true, "coreWhy": "Her Quiz 2 question 9 (teratogens do not cause only one kind of defect)", "stem": "True or False: A given teratogen always causes the same birth defect, whatever the time of exposure during gestation.", "options": [{"t": "True", "correct": false, "why": "Not true: the time of exposure changes the defect."}, {"t": "False", "correct": true, "why": "False. For a given teratogen, the time of exposure during gestation influences the type of effect (the retinoid study in hamsters)."}], "teach": "Teratogenesis is non-organ specific. For a given teratogen the time of exposure during gestation influences the type of effect: a retinoid given to hamster mothers on different gestation days produced small eyes, exencephaly, spina bifida, cleft palate, limb and tail defects. And different compounds can cause the same defect when given on different days (methanol day 7, TCDD day 11: cleft palate).", "quote": "So this is a classic example of why a teratogen. is not necessarily organ specific. It's because again, depending on the time of the mother's exposure during her pregnancy, you could end up with some of these other effects happening", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slides ‘Toxic Endpoints Non-Organ Specific: Teratogenesis Time of exposure’, ‘Teratogenesis with different compounds’; transcript 10/13"},
{"id": "NEW3-028", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "immune", "skill": "tell", "concept": "tf-idiosyncratic-low-frequency", "tags": ["smith", "tf"], "source": "slide", "stem": "True or False: \"Idiosyncratic\" is the proper term for all reactions that occur with low frequency.", "options": [{"t": "True", "correct": false, "why": "Not true: the slide calls that use improper."}, {"t": "False", "correct": true, "why": "False. The slide: \"Some people use 'idiosyncratic' to refer to all reactions that occur with low frequency; not proper use of the term.\""}], "teach": "Idiosyncratic toxicity: a genetically determined abnormal reactivity to a chemical; a response qualitatively similar to others' but extreme. Using the word for every low-frequency reaction is not proper use. Pharmacogenomics may help explain idiosyncratic responses, and the liver is the organ that tends to have them.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Idiosyncratic Toxicity’"},
{"id": "NEW3-029", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "zones", "skill": "recall", "concept": "tf-hepatotoxicity-always-zone3", "tags": ["smith", "tf"], "source": "both", "core": true, "coreWhy": "Her Quiz 2 question 8 (two reasons for site-specific liver damage) and poll 4", "stem": "True or False: Hepatotoxins always injure zone 3 of the liver.", "options": [{"t": "True", "correct": false, "why": "Not true: injury is site specific and depends on the toxin."}, {"t": "False", "correct": true, "why": "False. Zone 1 has the most oxygen, so oxygen-dependent enzymes there can make a toxic metabolite and injure zone 1. Acetaminophen injures zone 3, where CYP2E1 is highest."}], "teach": "Two reasons for site-specific hepatotoxicity: the oxygen gradient (highest in zone 1 near the inflow vessels, lowest in zone 3 near the central venule) and site-specific expression of metabolizing enzymes (many phase 2 enzymes in zone 1; CYP2E1 higher in zone 3). The zone injured depends on which enzyme activates the toxin and where.", "quote": "a lot of our phase 2 enzymes are in zone 1. And some of our P-450s are more in zone 3.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Reasons for Site-Specific Hepatotoxicity’; Smith_Quizzes_1-3_QA.pdf Quiz 2 question 8; transcript 10/14"},
{"id": "NEW3-030", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "neuro", "skill": "recall", "concept": "tf-bbb-developing-at-birth", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: The blood–brain barrier is still developing at birth.", "options": [{"t": "True", "correct": true, "why": "True, from the Neurotoxicity slide; she said it develops for several months to years."}, {"t": "False", "correct": false, "why": "The statement is on the slide."}], "teach": "Because the barrier is still developing, a medication that does not cross it in an adult might reach the brain of a newborn, so children's exposures need care.", "quote": "That blood-brain barrier is still developing at birth for several months to years. Therefore, we have to be very careful when we expose kids to certain medications", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Neurotoxicity’; transcript 10/14"},
{"id": "NEW3-031", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "neuro", "skill": "recall", "concept": "tf-remyelination-cns-pns", "tags": ["smith", "tf"], "source": "slide", "stem": "True or False: Remyelination is much less effective in the central nervous system than in the peripheral nervous system.", "options": [{"t": "True", "correct": true, "why": "True, from the figure legend of the patterns of neurotoxic injury."}, {"t": "False", "correct": false, "why": "The statement is in the figure legend: \"the process of remyelination is much less effective in the CNS than in the PNS.\""}], "teach": "Myelinopathy is disruption of myelin or injury to the myelinating cells (Schwann cells in the PNS, oligodendrocytes in the CNS). Myelinating cells divide and cover the denuded axon, but remyelination is much less effective in the CNS than in the PNS, and it takes a long time.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Types of Neurotoxicity’ (Figure 16-2 legend)"},
{"id": "NEW3-032", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "absorb", "skill": "recall", "concept": "tf-charcoal-binds-everything", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Activated charcoal binds every compound a person might ingest.", "options": [{"t": "True", "correct": false, "why": "Not true: its chemistry lets it grab only certain kinds of compounds."}, {"t": "False", "correct": true, "why": "False. Not every compound a person ingests is grabbed by charcoal, so it can't be used for everything."}], "teach": "Single-dose activated charcoal adsorbs certain compounds in the gut, and what it binds leaves in the feces. It works best soon after ingestion. Multiple-dose charcoal is limited to compounds that stick to charcoal and undergo enterohepatic recirculation.", "quote": "So not every compound a person ingests is going to be grabbed and absorbed by charcoal. So, can't use it for everything", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Toxicokinetic-Based Treatment Prevent Absorption’; transcript 10/14"},
{"id": "NEW3-033", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "metab", "skill": "recall", "concept": "tf-induce-enzymes", "tags": ["smith", "tf"], "source": "both", "core": true, "coreWhy": "Her Quiz 3 question 9 (we cannot enhance metabolism by inducing enzymes)", "stem": "True or False: To enhance the metabolism of a poison, the metabolizing enzymes are always induced.", "options": [{"t": "True", "correct": false, "why": "Not true: enzymes are not induced to treat a poisoning."}, {"t": "False", "correct": true, "why": "False. Induction takes a few days, too slow for a poisoned patient; instead, cofactors are given to accelerate the enzymes' reactions."}], "teach": "Enhance metabolism (detoxification): \"Cannot induce enzymes as takes too much time. Can accelerate metabolic actions of enzymes by administering cofactors.\" Examples: cyanide (thiosulfate for the body's rhodanese) and acetaminophen (N-acetylcysteine to replenish glutathione).", "quote": "You'll see tables of those ... which medication will induce which enzyme, but we can't do it fast enough. It takes a few days", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Toxicokinetic-Based Treatment Enhance Metabolism’; transcript 10/19"},
{"id": "NEW3-034", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "renal", "skill": "recall", "concept": "tf-ion-trapping-salicylate-phenobarbital", "tags": ["smith", "tf"], "source": "slide", "stem": "True or False: Ion trapping with sodium bicarbonate is very effective for salicylates and phenobarbital.", "options": [{"t": "True", "correct": true, "why": "True, from the Enhance Renal Elimination slide."}, {"t": "False", "correct": false, "why": "The slide says \"Very effective for salicylates and phenobarbital.\""}], "teach": "Sodium bicarbonate raises urine pH; the weakly acidic toxin becomes charged in the urine and is not reabsorbed. It is not done for weakly basic toxins. Her poisoning table lists IV sodium bicarbonate for salicylates (renal ion trapping to enhance elimination).", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Toxicokinetic-Based Treatment Enhance Renal Elimination’"},
{"id": "NEW3-035", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "inact", "skill": "recall", "concept": "tf-inactivation-before-absorption", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Inactivation of a poison applies only to poison still in the gut, before it is absorbed.", "options": [{"t": "True", "correct": false, "why": "Not true: inactivation is for toxins that have already entered the circulation."}, {"t": "False", "correct": true, "why": "False. The slide: inactivation is \"Done to reduce activity of toxins that have entered circulation and are not readily eliminated.\""}], "teach": "Inactivation: the inactivator binds the toxin and prevents its interaction with target tissues; the toxin-inactivator complex is cleared; the inactivator must have high affinity for the toxin; the complex must have low toxicity (she said no toxicity). Examples: heavy metal chelators, antivenoms and antibodies such as digoxin immune Fab. Keeping a poison in the gut is prevention of absorption, a toxicokinetic method.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Inactivation of Poisons’; transcript 10/19"},
{"id": "NEW3-036", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "pharmsite", "skill": "recall", "concept": "tf-pralidoxime-aged", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Pralidoxime cannot pull an aged organophosphate off acetylcholinesterase.", "options": [{"t": "True", "correct": true, "why": "True: once part of the organophosphate falls off (aging), pralidoxime can't remove it."}, {"t": "False", "correct": false, "why": "The statement is true. After aging, the enzyme is permanently bound."}], "teach": "Pralidoxime removes the toxin from the active site: it pulls the organophosphate off acetylcholinesterase onto itself. Some organophosphates, by their chemical structure, lose a part after binding; then the enzyme is permanently bound and pralidoxime cannot pull it off. That is aging.", "quote": "the acetylcholinesterase is permanently bound by that organophosphate, and we can't pull it off the acetylcholinesterase using pralodoxine. That's called aging of your organophosphate.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slides ‘Pharmacological Treatment: Treatment Removes Toxin from Active Site’, ‘Pralidoxime example’; transcript 10/19"},
{"id": "NEW3-037", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "recall", "concept": "tf-nac-never-after-8h", "tags": ["smith", "tf"], "source": "slide", "core": true, "coreWhy": "Her key's special considerations column (acetaminophen)", "stem": "True or False: Once N-acetylcysteine loses effectiveness, about 8 hours after an acetaminophen overdose, it should never be given.", "options": [{"t": "True", "correct": false, "why": "Not true: her key says to still give it."}, {"t": "False", "correct": true, "why": "False. Her key: \"At what time after OD does the antidote lose effectiveness? About 8 hours after overdose. Should you still give it past that time point? Yes.\""}], "teach": "Acetaminophen row: nausea/vomiting, clinical signs of liver failure; acetaminophen levels can be measured in the blood. Antidote N-acetylcysteine, which replenishes glutathione. It loses effectiveness about 8 hours after overdose, and it is still given past that point.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Acetaminophen’, special considerations; transcript 10/20"},
{"id": "NEW3-038", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "recall", "concept": "tf-digoxin-total-rises", "tags": ["smith", "tf"], "source": "slide", "core": true, "coreWhy": "Her key's special considerations column (digoxin)", "stem": "True or False: After digoxin-specific antibody fragments are given, the total serum digoxin concentration increases.", "options": [{"t": "True", "correct": true, "why": "True: free plus Fab-bound digoxin is measured together."}, {"t": "False", "correct": false, "why": "The statement is true, per her key."}], "teach": "Her key: \"The total dig concentration (Free and bound to Fab) will be increased; can't use this measurement to calculate more Fab doses.\" The antidote binds digoxin, and the complex is renally eliminated.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Digoxin’, special considerations; transcript 10/20"},
{"id": "NEW3-039", "lecture": "L17", "prof": "Smith", "tier": "new", "topic": "L17", "sub": "variant", "skill": "recall", "concept": "tf-rare-variant", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: A genetic variation present in less than 1% of a population is called a rare variant.", "options": [{"t": "True", "correct": true, "why": "True: under 1% is a rare variant; at least 1% is a polymorphism."}, {"t": "False", "correct": false, "why": "The statement is true, from the Polymorphism slide."}], "teach": "Polymorphism: a variation in DNA sequence present in at least 1% of the population. Rare variant: present in less than 1%. The term rare variant is newer; it came in as patients with bad responses were found to carry variations never seen before.", "quote": "A rare variant is a genetic variation that is occurring in less than 1% of the population.", "cite": "Intro_to_PGx_Lecture_Students_Fall_2026.pdf slide ‘Polymorphism’ (p. 14); transcript 10/20"},
{"id": "NEW3-040", "lecture": "L17", "prof": "Smith", "tier": "new", "topic": "L17", "sub": "variant", "skill": "recall", "concept": "tf-only-snps-polymorphic", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Only a single nucleotide change can be called a polymorphism.", "options": [{"t": "True", "correct": false, "why": "Not true: any kind of genetic variation occurring in at least 1% of a population is a polymorphism."}, {"t": "False", "correct": true, "why": "False. The slide lists more than one nucleotide change, an entire gene insertion or deletion, and extra copies of a gene as other types of polymorphism."}], "teach": "A SNP (single nucleotide polymorphism) is the most common type. Other types: more than one nucleotide change, an entire gene insertion or deletion, extra copies of a gene, and more. The word is defined by frequency (at least 1%), not by the size of the change.", "quote": "so any kind of genetic. Craziness that you can think of, if it happens in more than 1 in 1% or more of the population, by definition it's polymorphic.", "cite": "Intro_to_PGx_Lecture_Students_Fall_2026.pdf slide ‘Polymorphism’ (p. 14); transcript 10/20"},
{"id": "NEW3-041", "lecture": "GRG3", "prof": "Smith", "tier": "new", "topic": "GRG3", "sub": "ccb", "skill": "apply", "concept": "tf-mr-ccb-always-hospital", "tags": ["smith", "tf"], "source": "both", "stem": "True or False: Every asymptomatic patient who took a modified-release calcium channel blocker must go to a hospital, however long ago the ingestion was.", "options": [{"t": "True", "correct": false, "why": "Not true: the window matters."}, {"t": "False", "correct": true, "why": "False. Modified-release calcium channel blocker other than verapamil: within 18 hours, get them to a hospital; after 18 hours, call the Poison Center, and they can probably be managed at home. For modified-release verapamil the window is 24 hours."}], "teach": "Windows for an asymptomatic patient, her key: immediate release (both classes; sotalol excepted for beta blockers) 6 hours; sustained-release beta blocker 8 hours; modified-release calcium channel blocker except verapamil 18 hours; modified-release verapamil 24 hours. Inside the window: hospital. After it: call the Poison Center.", "quote": "they're asymptomatic, and they ingested the modified release product, and you found them within 18 hours of ingestion. You need to get him in.", "cite": "Readingguideforoutofhospitalguidelines2026KEY.docx, Calcium Channel Blockers, question 2; transcript 10/19"},
{"id": "NEW3-042", "lecture": "RMK3", "prof": "Smith", "tier": "new", "topic": "RMK3", "sub": "exposure", "skill": "recall", "concept": "tf-wildlife-more-significant", "tags": ["smith", "tf"], "source": "both", "core": true, "coreWhy": "Her discussion guide key; her words 10/13: \"this is testable material\"", "stem": "True or False: For pharmaceuticals in water, aquatic wildlife exposure is more significant than human exposure.", "options": [{"t": "True", "correct": true, "why": "True: her key answers \"Which is more significant?\" with aquatic wildlife exposure."}, {"t": "False", "correct": false, "why": "The statement is true, per her key."}], "teach": "Aquatic wildlife: exposure for their entire life, repeated, constant if their home range is continually contaminated, by drinking water, food and the skin. Humans: depends on how people are exposed and where they live, mostly by drinking water.", "quote": "your patient, they're probably OK. We are worried about wildlife.", "cite": "KeyDiscussionGuideRodriguez-MozazandWeinberg2026.docx, row Exposure; transcript 10/13"},
{"id": "NEW3-043", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "drug", "concept": "pair-poison-antidote", "tags": ["smith", "pairing"], "source": "slide", "core": true, "coreWhy": "Her key's antidote column", "stem": "Which pairing of poisoning and antidote is INCORRECT?", "options": [{"t": "Opioids – naloxone", "correct": false, "why": "Correct pairing, from the opioids row."}, {"t": "Iron – deferoxamine", "correct": false, "why": "Correct pairing, from the iron row."}, {"t": "Sulfonylureas – octreotide", "correct": false, "why": "Correct pairing, from the sulfonylureas and meglitinide row."}, {"t": "Organophosphates – flumazenil", "correct": true, "why": "Incorrect. Flumazenil is the benzodiazepine antidote; organophosphate insecticides are treated with atropine and pralidoxime."}], "teach": "Antidotes in her key: acetaminophen, N-acetylcysteine; toxic alcohols, ethanol or fomepizole; benzodiazepines, flumazenil; beta blockers and calcium channel blockers, atropine, calcium, glucagon, HIET, vasopressors, IV 20% fatty acid emulsion; digoxin, digoxin-specific antibody fragments; tricyclic antidepressants, IV fluids, dopamine or norepinephrine, sodium bicarbonate; opioids, naloxone; salicylates, supportive care and IV sodium bicarbonate; sulfonylureas and meglitinide, octreotide; iron, deferoxamine; organophosphates, atropine and pralidoxime.", "cite": "PoisoningTreatmentTable2026KEY.pdf antidote column; transcript 10/20"},
{"id": "NEW3-044", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "match", "skill": "drug", "concept": "pair-antidote-mechanism", "tags": ["smith", "pairing"], "source": "slide", "core": true, "coreWhy": "Her key's mechanism column; her Quiz 3 questions 3 and 4", "stem": "Which pairing of antidote and mechanism of action is INCORRECT?", "options": [{"t": "N-acetylcysteine – replenishes glutathione", "correct": false, "why": "Correct pairing, from the acetaminophen row."}, {"t": "Fomepizole – inhibits alcohol dehydrogenase", "correct": false, "why": "Correct pairing, from the toxic alcohols row."}, {"t": "Octreotide – inhibits insulin release from the pancreas", "correct": false, "why": "Correct pairing, from the sulfonylureas row."}, {"t": "Pralidoxime – muscarinic acetylcholine receptor antagonist", "correct": true, "why": "Incorrect. That is atropine's mechanism in the organophosphate row; pralidoxime removes the organophosphate from acetylcholinesterase."}], "teach": "Mechanisms in her key: NAC replenishes glutathione; ethanol and fomepizole inhibit alcohol dehydrogenase; flumazenil is a competitive antagonist of the benzodiazepine receptor; glucagon increases cardiac cellular cAMP; digoxin Fab binds digoxin, which is renally eliminated; naloxone is a competitive antagonist of opioid receptors; sodium bicarbonate gives renal ion trapping (salicylates) or counteracts sodium-channel inhibition (TCAs); octreotide inhibits insulin release; deferoxamine chelates circulating ferric iron; atropine is a muscarinic receptor antagonist; pralidoxime removes OP from acetylcholinesterase.", "cite": "PoisoningTreatmentTable2026KEY.pdf mechanism of action column; transcript 10/20"},
{"id": "NEW3-045", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "bioact", "skill": "tell", "concept": "pair-tk-method-example", "tags": ["smith", "pairing"], "source": "both", "core": true, "coreWhy": "Her Quiz 3 question 1; her words 10/20: you do need to know those examples", "stem": "Which pairing of toxicokinetic method and example is INCORRECT?", "options": [{"t": "Prevent absorption – activated charcoal", "correct": false, "why": "Correct pairing."}, {"t": "Inhibit bioactivation – fomepizole for methanol", "correct": false, "why": "Correct pairing; her Quiz 3 question 1."}, {"t": "Enhance renal elimination – bicarbonate for salicylates", "correct": false, "why": "Correct pairing (ion trapping)."}, {"t": "Enhance metabolism – ethanol for ethylene glycol", "correct": true, "why": "Incorrect. Ethanol for ethylene glycol inhibits bioactivation by alcohol dehydrogenase. The enhance-metabolism examples are cyanide and acetaminophen."}], "teach": "Examples of the four toxicokinetic methods: prevent absorption (emesis, gastric lavage, whole bowel irrigation, activated charcoal); inhibit bioactivation (ethanol or fomepizole for methanol and ethylene glycol); enhance metabolism with cofactors (cyanide, acetaminophen with N-acetylcysteine); enhance elimination (sodium bicarbonate ion trapping for salicylates and phenobarbital; extracorporeal methods).", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slides ‘Toxicokinetic-Based Treatment’ through ‘Enhance Renal Elimination’; transcript 10/20"},
{"id": "NEW3-046", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "pharmrec", "skill": "tell", "concept": "pair-pharm-category-example", "tags": ["smith", "pairing"], "source": "both", "stem": "Which pairing of pharmacological treatment category and example is INCORRECT?", "options": [{"t": "Receptor antagonist – naloxone for opioids", "correct": false, "why": "Correct pairing."}, {"t": "Receptor agonist – physostigmine for jimsonweed", "correct": false, "why": "Correct pairing: physostigmine blocks AChE, so it acts like a receptor agonist."}, {"t": "By-passes an inhibited pathway – vitamin K for warfarin", "correct": false, "why": "Correct pairing."}, {"t": "Removes toxin from the active site – flumazenil", "correct": true, "why": "Incorrect. Flumazenil is a receptor antagonist at the GABA-A (benzodiazepine) receptor. Removal from the active site: pralidoxime, oxygen for CO, the cyanide scheme."}], "teach": "Receptor antagonist: naloxone (opioids), flumazenil (benzodiazepines), atropine (organophosphates). Receptor agonist: physostigmine (belladonna alkaloids such as jimsonweed). Removes the toxin from the active site: methemoglobin in cyanide poisoning, oxygen for carbon monoxide, pralidoxime for organophosphates. By-passes an inhibited pathway: vitamin K for warfarin.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slides ‘Pharmacological Treatment’ through ‘Treatment by-passes an inhibited pathway’; transcript 10/20"},
{"id": "NEW3-047", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "inact", "skill": "drug", "concept": "pair-chelator-metal", "tags": ["smith", "pairing"], "source": "both", "core": true, "coreWhy": "Her words 10/19: know the chelating agents and which metals they bind", "stem": "Which pairing of chelating agent and metal is INCORRECT?", "options": [{"t": "Deferoxamine – iron", "correct": false, "why": "Correct pairing."}, {"t": "Penicillamine – copper", "correct": false, "why": "Correct pairing; used with trientine in Wilson's disease."}, {"t": "Succimer – lead", "correct": false, "why": "Correct pairing; succimer chelates lead, cadmium, mercury and arsenic."}, {"t": "Deferasirox – lead", "correct": true, "why": "Incorrect. Deferasirox chelates iron; it is the orally bioavailable iron chelator."}], "teach": "Chelator table: edetate disodium, lead; dimercaprol (BAL), gold, arsenic, lead, mercury; succimer, lead, cadmium, mercury, arsenic; deferoxamine, iron; deferasirox, iron (orally bioavailable); penicillamine and trientine, copper (Wilson's disease).", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Inactivation of Poisons: Example Chelating Agents’; transcript 10/19"},
{"id": "NEW3-048", "lecture": "L17", "prof": "Smith", "tier": "new", "topic": "L17", "sub": "variant", "skill": "recall", "concept": "pair-pgx-term-definition", "tags": ["smith", "pairing"], "source": "both", "stem": "Which pairing of term and definition is INCORRECT?", "options": [{"t": "Wild type – the version thought to be most common", "correct": false, "why": "Correct pairing, from the Wildtype vs Variant slide."}, {"t": "Polymorphism – present in at least 1% of a population", "correct": false, "why": "Correct pairing, from the Polymorphism slide."}, {"t": "Haplotype – a set of alleles at loci on one chromosome", "correct": false, "why": "Correct pairing: alleles at multiple loci that co-exist on the same chromosome."}, {"t": "Allele frequency – frequency of a genotype in a population", "correct": true, "why": "Incorrect. That is genotype frequency. Allele frequency is the relative frequency of an allele in a population."}], "teach": "Terms through p. 21: wild type (thought to be most common) and variant (not thought to be common); polymorphism (at least 1%) and rare variant (less than 1%); SNP; allele; homozygosity and heterozygosity; genotype and phenotype; haplotype and linkage disequilibrium; allele frequency and genotype frequency; Hardy-Weinberg equilibrium.", "cite": "Intro_to_PGx_Lecture_Students_Fall_2026.pdf slides ‘Wildtype vs Variant’ (p. 13), ‘Polymorphism’ (p. 14), ‘Haplotype’ (p. 19), ‘Frequencies in Pharmacogenomics’ (p. 21); transcript 10/20"},
{"id": "NEW3-049", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "neuro", "skill": "tell", "concept": "pair-neurotox-pattern", "tags": ["smith", "pairing"], "source": "both", "core": true, "coreWhy": "Her Quiz 2 question 6 (neuronopathy)", "stem": "Which pairing of neurotoxic injury and description is INCORRECT?", "options": [{"t": "Neuronopathy – death of the entire neuron", "correct": false, "why": "Correct pairing (neuron B)."}, {"t": "Myelinopathy – disruption of myelin", "correct": false, "why": "Correct pairing (neuron D): disruption of myelin or injury to the myelinating cells."}, {"t": "Neurotransmission toxicity – excess stimulation", "correct": false, "why": "Correct pairing (neuron E): blocking excitation or excessive stimulation."}, {"t": "Axonopathy – injury to the myelinating cells", "correct": true, "why": "Incorrect. In axonopathy the axon is the primary site of injury and degenerates; injury to the myelinating cells is myelinopathy."}], "teach": "Patterns of neurotoxic injury (Figure 16-2): neuronopathy, death of the entire neuron; axonopathy, the axon is the primary site of injury and degenerates; myelinopathy, disruption of myelin or selective injury to the myelinating cells; neurotransmission toxicity, interruption of neurotransmission by blocking excitation or by excessive stimulation, with no cell death (organophosphates).", "quote": "What did that neurotoxin do to this nerve cell? Killed the whole thing", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Types of Neurotoxicity’ (Figure 16-2); transcript 10/14"},
{"id": "NEW3-050", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "ontarget", "skill": "tell", "concept": "pair-drug-target-type", "tags": ["smith", "pairing"], "source": "slide", "stem": "Which pairing of drug effect and type of adverse effect is INCORRECT?", "options": [{"t": "Diphenhydramine sleepiness – on-target, wrong tissue", "correct": false, "why": "Correct pairing: the correct receptor in the wrong tissue."}, {"t": "Terfenadine arrhythmia – off-target receptor", "correct": false, "why": "Correct pairing: inhibition of a cardiac potassium channel."}, {"t": "Thalidomide teratogenesis – off-target enantiomer", "correct": false, "why": "Correct pairing: the S-enantiomer is a potent teratogen."}, {"t": "Propranolol asthma – on-target, dose too high", "correct": true, "why": "Incorrect. Asthma exacerbation with propranolol is off-target: activation of an unintended receptor subtype, beta-2 receptors in airway smooth muscle."}], "teach": "On-target: dose at the receptor too high; correct receptor in the wrong tissue (sleepiness with diphenhydramine). Off-target: drug hits an unintended receptor (terfenadine, cardiac potassium channel); enantiomer hits an unintended receptor (racemic thalidomide, S-enantiomer); unintended receptor subtype (propranolol, beta-2 in the airway).", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slides ‘Toxic Endpoints On-Target Examples’, ‘Toxic Endpoints Off-Target Examples’"},
{"id": "NEW3-051", "lecture": "GRG3", "prof": "Smith", "tier": "new", "topic": "GRG3", "sub": "both", "skill": "recall", "concept": "pair-formulation-window", "tags": ["smith", "pairing"], "source": "both", "core": true, "coreWhy": "Her words 10/19: know those time frames, which formulation is OK at which time frame", "stem": "For an asymptomatic patient, which pairing of product and hospital window after ingestion is INCORRECT?", "options": [{"t": "Immediate-release calcium channel blocker – 6 hours", "correct": false, "why": "Correct pairing."}, {"t": "Sustained-release beta blocker – 8 hours", "correct": false, "why": "Correct pairing."}, {"t": "Modified-release verapamil – 24 hours", "correct": false, "why": "Correct pairing."}, {"t": "Other modified-release calcium channel blocker – 8 hours", "correct": true, "why": "Incorrect. A modified-release calcium channel blocker other than verapamil has an 18-hour window; 8 hours is the sustained-release beta blocker."}], "teach": "Her key's windows for an asymptomatic patient: immediate-release product (calcium channel blocker, or beta blocker except sotalol) 6 hours; sustained-release beta blocker 8 hours; modified-release calcium channel blocker except verapamil 18 hours; modified-release verapamil 24 hours. Found within the window: get them to a hospital. Found after it: call the Poison Center; they can probably be managed at home.", "cite": "Readingguideforoutofhospitalguidelines2026KEY.docx, question 2, both columns; transcript 10/19"},
{"id": "NEW3-052", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "apply", "concept": "case-opioid", "tags": ["smith", "case"], "source": "slide", "core": true, "coreWhy": "Her key's symptom column (opioids); her Quiz 3 question 5", "stem": "A man is found barely arousable. His heart rate and breathing are slow, and his pupils are very small. Which poisoning is most likely?", "options": [{"t": "Opioids", "correct": true, "why": "Her key: somnolence, coma, decreased heart and breath rates, decreased pupils."}, {"t": "Benzodiazepines", "correct": false, "why": "Benzodiazepine overdose: CNS depression with relatively normal vitals."}, {"t": "Tricyclic antidepressants", "correct": false, "why": "TCA overdose: tachycardia and dilated pupils."}, {"t": "Calcium channel blockers", "correct": false, "why": "Calcium channel blocker overdose: hypotension and bradycardia, but often alert."}], "teach": "Opioids row: somnolence, coma, decreased heart and breath rates, decreased pupils. Antidote: naloxone, a competitive antagonist of opioid receptors; in chronic opioid users it can trigger withdrawal.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Opioids’; transcript 10/20"},
{"id": "NEW3-053", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "apply", "concept": "case-benzodiazepine", "tags": ["smith", "case"], "source": "slide", "stem": "A woman is deeply drowsy and hard to wake. Her heart rate, blood pressure, breathing and pupils are normal. Which poisoning is most likely?", "options": [{"t": "Opioids", "correct": false, "why": "Opioid overdose lowers heart and breath rates and shrinks the pupils."}, {"t": "Benzodiazepines", "correct": true, "why": "Her key: CNS depression and relatively normal vitals."}, {"t": "Beta blockers", "correct": false, "why": "Beta-blocker overdose: hypotension and bradycardia."}, {"t": "Salicylates", "correct": false, "why": "Salicylate overdose: hyperventilation, hyperthermia, confusion and seizures."}], "teach": "Benzodiazepines row: CNS depression and relatively normal vitals; benzodiazepine levels can be measured in the blood. Antidote: flumazenil, a competitive antagonist of the benzodiazepine receptor, which can cause withdrawal in a benzodiazepine-dependent patient.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Benzodiazepines’; transcript 10/20"},
{"id": "NEW3-054", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "apply", "concept": "case-bb-vs-ccb-confused", "tags": ["smith", "case"], "source": "slide", "core": true, "coreWhy": "Her key's special considerations: what distinguishes beta blocker from calcium channel blocker overdose", "stem": "A patient took a handful of heart pills. His blood pressure is low, his heart rate is slow, and he is confused and not making sense. Which poisoning is most likely?", "options": [{"t": "Beta blockers", "correct": true, "why": "Most likely: hypotension and bradycardia with altered mental status. Her key: \"BB OD may have altered mental status.\""}, {"t": "Calcium channel blockers", "correct": false, "why": "Also hypotension and bradycardia, but her key says the patient is often alert."}, {"t": "Digoxin", "correct": false, "why": "Digoxin overdose: bradycardia and arrhythmias with elevated serum potassium and nausea/vomiting."}, {"t": "Tricyclic antidepressants", "correct": false, "why": "TCA overdose: tachycardia, not bradycardia."}], "teach": "Beta blockers: hypotension, bradycardia, altered mental status, respiratory depression. Calcium channel blockers: hypotension, bradycardia, but often alert. Her special-considerations answer: \"BB OD may have altered mental status.\" The two share the same antidote list.", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Beta blockers’, ‘Calcium channel blockers’; transcript 10/20"},
{"id": "NEW3-055", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "apply", "concept": "case-ccb-alert", "tags": ["smith", "case"], "source": "slide", "core": true, "coreWhy": "Her key's special considerations (BB vs CCB); her Quiz 3 questions 2 and 3", "stem": "A patient took a handful of blood pressure pills. His blood pressure is low, his heart rate is slow, and he is alert and talking. Which poisoning is most likely?", "options": [{"t": "Beta blockers", "correct": false, "why": "Also hypotension and bradycardia, but beta-blocker overdose may have altered mental status."}, {"t": "Calcium channel blockers", "correct": true, "why": "Most likely: her key lists hypotension, bradycardia, but often alert."}, {"t": "Opioids", "correct": false, "why": "Opioid overdose: somnolence or coma with decreased breath rate and small pupils."}, {"t": "Iron", "correct": false, "why": "Iron causes hypotension with tachycardia, after vomiting, abdominal pain and diarrhea."}], "teach": "Calcium channel blockers row: hypotension, bradycardia, but often alert. Antidotes: the same as for beta-blocker overdose (atropine, calcium, glucagon, HIET, vasopressors, IV 20% fatty acid emulsion). Her Quiz 3 asked for HIET in an extended-release calcium channel blocker overdose and for glucagon's mechanism (increases cAMP).", "cite": "PoisoningTreatmentTable2026KEY.pdf rows ‘Calcium channel blockers’, ‘Beta blockers’; transcript 10/20"},
{"id": "NEW3-056", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "apply", "concept": "case-digoxin", "tags": ["smith", "case"], "source": "slide", "core": true, "coreWhy": "Her key's digoxin row", "stem": "An older patient on a heart medication has nausea and vomiting, a slow, irregular heart rhythm, and an elevated serum potassium. A blood level confirms the drug. What is the antidote?", "options": [{"t": "Glucagon", "correct": false, "why": "Glucagon is on the beta-blocker and calcium channel blocker list; it raises cardiac cAMP."}, {"t": "Digoxin specific antibody fragments", "correct": true, "why": "Digoxin overdose: bradycardia, arrhythmias, elevated serum potassium, nausea/vomiting; antidote digoxin-specific antibody fragments."}, {"t": "Atropine and pralidoxime", "correct": false, "why": "These are the organophosphate antidotes."}, {"t": "Calcium", "correct": false, "why": "Calcium is on the beta-blocker and calcium channel blocker list, to drive calcium into cardiac cells."}], "teach": "Digoxin row: bradycardia, arrhythmias, elevated serum potassium, nausea/vomiting; digoxin levels can be measured in the blood. Antidote: digoxin-specific antibody fragments, which bind digoxin; the complex is renally eliminated. After the antidote, total digoxin (free and bound to Fab) rises, so levels can't be used to calculate more Fab doses.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Digoxin’; transcript 10/20"},
{"id": "NEW3-057", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cns", "skill": "apply", "concept": "case-tca-qrs", "tags": ["smith", "case"], "source": "slide", "core": true, "coreWhy": "Her key's tricyclic antidepressant row", "stem": "A patient is agitated with a seizure, a fast heart rate, dilated pupils, a dry mouth, and an elongated QRS interval. Sodium bicarbonate is given. What is it doing here?", "options": [{"t": "Counteracting inhibition of cardiac sodium channels", "correct": true, "why": "Her key, tricyclic antidepressants row: sodium bicarbonate counteracts the inhibition of cardiac sodium channels."}, {"t": "Renal ion trapping to enhance elimination", "correct": false, "why": "That is sodium bicarbonate's mechanism in the salicylates row."}, {"t": "Increasing cardiac cellular cAMP", "correct": false, "why": "That is glucagon's mechanism in beta-blocker overdose."}, {"t": "Acting as a sink for a lipophilic drug", "correct": false, "why": "That is IV 20% fatty acid emulsion, in beta-blocker overdose."}], "teach": "The picture is tricyclic antidepressant overdose: tachycardia, dilated pupils, dry mouth, agitation, seizures, sometimes vasodilation, elongated QRS interval, reduced cardiac contractility. Treatments: IV fluids and dopamine or norepinephrine (supportive care, to maintain blood pressure) and sodium bicarbonate for the elongated QRS, which counteracts the inhibition of cardiac sodium channels.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Tricyclic Antidepressants’; transcript 10/20"},
{"id": "NEW3-058", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "apply", "concept": "case-salicylate", "tags": ["smith", "case"], "source": "slide", "stem": "A patient is breathing fast and deep, and blood gases show a respiratory alkalosis, followed hours later by a metabolic acidosis. The patient has a high temperature and is confused. Which poisoning is most likely?", "options": [{"t": "Salicylates", "correct": true, "why": "Her key: hyperventilation and respiratory alkalosis then metabolic acidosis, hyperthermia, confusion and seizures."}, {"t": "Methanol", "correct": false, "why": "Methanol causes an anion-gap metabolic acidosis with ocular toxicity, without the respiratory alkalosis first."}, {"t": "Benzodiazepines", "correct": false, "why": "Benzodiazepines cause CNS depression with relatively normal vitals."}, {"t": "Sulfonylureas", "correct": false, "why": "Sulfonylurea and meglitinide overdose causes hypoglycemia."}], "teach": "Salicylates row: hyperventilation and respiratory alkalosis, then metabolic acidosis, hyperthermia, confusion and seizures. Treatment: supportive care and IV sodium bicarbonate, which works by renal ion trapping to enhance elimination.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Salicylates’; transcript 10/20"},
{"id": "NEW3-059", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "apply", "concept": "case-sulfonylurea", "tags": ["smith", "case"], "source": "slide", "stem": "A patient with type 2 diabetes took extra doses of his sulfonylurea and is sweaty and confused, with a low blood glucose. Which antidote is listed for this overdose?", "options": [{"t": "Glucagon", "correct": false, "why": "Glucagon is listed for beta-blocker and calcium channel blocker overdose (increases cardiac cAMP)."}, {"t": "Flumazenil", "correct": false, "why": "Flumazenil is the benzodiazepine antidote."}, {"t": "Octreotide", "correct": true, "why": "Her key: sulfonylureas and meglitinide, hypoglycemia; antidote octreotide, which inhibits insulin release from the pancreas."}, {"t": "Deferoxamine", "correct": false, "why": "Deferoxamine is the iron antidote."}], "teach": "Sulfonylureas and meglitinide row: hypoglycemia. Antidote: octreotide, which inhibits insulin release from the pancreas.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Sulfonylureas and miglitinide’; transcript 10/20"},
{"id": "NEW3-060", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "apply", "concept": "case-iron", "tags": ["smith", "case"], "source": "slide", "stem": "A toddler vomited and had abdominal pain and diarrhea within a few hours of an ingestion. Later that day, between 6 and 24 hours after the ingestion, he is lethargic, with bloody vomiting, low blood pressure and a fast heart rate. Which poisoning is most likely?", "options": [{"t": "Acetaminophen", "correct": false, "why": "Acetaminophen: nausea/vomiting and clinical signs of liver failure, without bloody vomiting or shock."}, {"t": "Iron", "correct": true, "why": "Her key's iron time course: vomiting, abdominal pain and diarrhea within 1 to 6 hours; lethargy, coma, seizures, bloody vomiting, bloody diarrhea, shock, hypotension and tachycardia within 6 to 24 hours."}, {"t": "Digoxin", "correct": false, "why": "Digoxin overdose: bradycardia, arrhythmias, elevated potassium."}, {"t": "Opioids", "correct": false, "why": "Opioids slow the heart and breathing."}], "teach": "Iron row: vomiting, abdominal pain and diarrhea within 1 to 6 hours; lethargy, coma, seizures, bloody vomiting, bloody diarrhea and shock within 6 to 24 hours; hypotension and tachycardia within 6 to 24 hours; liver dysfunction and failure possible in 2 to 5 days. Antidote: deferoxamine, which chelates the circulating ferric iron.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Iron’; transcript 10/20"},
{"id": "NEW3-061", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "ironop", "skill": "apply", "concept": "case-organophosphate-atropine", "tags": ["smith", "case"], "source": "slide", "core": true, "coreWhy": "Her key's organophosphate row; her Quiz 3 question 4", "stem": "A farm worker who was spraying insecticide is drooling, tearing, urinating and has diarrhea and vomiting. Atropine is given. What is its mechanism of action here?", "options": [{"t": "Removes the insecticide from acetylcholinesterase", "correct": false, "why": "That is pralidoxime, the second organophosphate antidote."}, {"t": "Muscarinic acetylcholine receptor antagonist", "correct": true, "why": "Her key, organophosphate row: atropine is a muscarinic acetylcholine receptor antagonist."}, {"t": "Competitive antagonist of opioid receptors", "correct": false, "why": "That is naloxone."}, {"t": "Competitive antagonist of the benzodiazepine receptor", "correct": false, "why": "That is flumazenil."}], "teach": "Organophosphate insecticides row: acetylcholine excess, SLUDGE or DUMBELLS. Antidotes: atropine, a muscarinic acetylcholine receptor antagonist, and pralidoxime, which removes the organophosphate from acetylcholinesterase (unless it has aged).", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Organophosphate Insecticides’; transcript 10/20"},
{"id": "NEW3-062", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "apply", "concept": "case-acetaminophen-nac", "tags": ["smith", "case"], "source": "slide", "core": true, "coreWhy": "Her key's acetaminophen row", "stem": "A student swallowed a bottle of acetaminophen a few hours ago and is nauseated and vomiting; the blood acetaminophen level is high. N-acetylcysteine is started. What is its mechanism of action?", "options": [{"t": "Inhibits alcohol dehydrogenase", "correct": false, "why": "That is ethanol and fomepizole, for toxic alcohols."}, {"t": "Chelates the circulating ferric iron", "correct": false, "why": "That is deferoxamine, for iron."}, {"t": "Replenishes glutathione", "correct": true, "why": "Her key: N-acetylcysteine replenishes glutathione, which conjugates NAPQI."}, {"t": "Renal ion trapping to enhance elimination", "correct": false, "why": "That is sodium bicarbonate, for salicylates."}], "teach": "Acetaminophen row: nausea/vomiting, clinical signs of liver failure; acetaminophen levels can be measured in the blood. N-acetylcysteine replenishes glutathione; it loses effectiveness about 8 hours after overdose but is still given past that point. On 10/19: NAC supplies what the body needs to make more glutathione, which conjugates NAPQI with the help of the GST enzymes.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Acetaminophen’; transcript 10/20"},
{"id": "NEW3-063", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "apply", "concept": "case-methanol", "tags": ["smith", "case"], "source": "slide", "stem": "A man drank homemade liquor. Hours later his vision is blurred and his labs show an anion-gap metabolic acidosis. Which poisoning is most likely?", "options": [{"t": "Ethylene glycol", "correct": false, "why": "Ethylene glycol's metabolites crystallize in the microvasculature; renal toxicity is common."}, {"t": "Salicylates", "correct": false, "why": "Salicylates give hyperventilation and respiratory alkalosis before the metabolic acidosis, with hyperthermia."}, {"t": "Iron", "correct": false, "why": "Iron gives vomiting, abdominal pain and diarrhea, then shock."}, {"t": "Methanol", "correct": true, "why": "Most likely: methanol's active metabolites cause an anion-gap metabolic acidosis and ocular toxicity."}], "teach": "Toxic alcohols row: methanol's active metabolites cause anion-gap metabolic acidosis and ocular toxicity (formic acid damages the retina); ethylene glycol's metabolites crystallize in the microvasculature, and renal toxicity is common. Antidote for both: ethanol or fomepizole (inhibition of alcohol dehydrogenase); fomepizole is the stronger inhibitor with fewer adverse effects.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Toxic alcohols’; transcript 10/20"},
{"id": "NEW3-064", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "admet", "skill": "recall", "type": "fill", "concept": "fill-bioactivation", "tags": ["smith", "fill"], "source": "both", "stem": "Metabolism of a compound to something more harmful than the compound originally taken is called ____.", "answer": "bioactivation", "accept": ["bioactivation", "toxication", "metabolic activation", "toxification"], "bank": ["bioactivation", "detoxification", "conjugation", "hormesis", "potentiation", "elimination"], "teach": "Her word is bioactivation; toxication and metabolic activation mean the same. The opposite, metabolism to something less harmful and easier to eliminate, is detoxification. Acetaminophen to NAPQI by CYP2E1 is her classic example.", "quote": "I use the word bioactivation for that. Some people use the word toxication, toxification.", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slides ‘ADME: Metabolism’, ‘Example of Bioactivation’; transcript 10/9"},
{"id": "NEW3-065", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "admet", "skill": "recall", "type": "fill", "concept": "fill-cyp2e1", "tags": ["smith", "fill"], "source": "both", "stem": "When the phase 2 enzymes cannot handle an acetaminophen dose, ____ metabolizes it to the liver-toxic metabolite NAPQI.", "answer": "CYP2E1", "accept": ["CYP2E1", "2E1", "cytochrome P450 2E1", "P450 2E1"], "bank": ["CYP2E1", "CYP2C19", "CYP2C9", "CYP2D6", "glutathione S-transferase", "sulfotransferase"], "teach": "Most of a therapeutic dose of acetaminophen is conjugated by the glucuronosyl transferases and sulfotransferases (detoxification). When they are overwhelmed, CYP2E1 forms NAPQI (bioactivation). Alcohol can induce CYP2E1, and genetic variation can lower the phase 2 enzymes, so NAPQI can form even at doses under 4 g a day.", "quote": "Specifically P4452E1. We'll do this work to create that nasty NAQI", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘Example of Bioactivation’; transcript 10/9"},
{"id": "NEW3-066", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "dose", "skill": "recall", "type": "fill", "concept": "fill-paracelsus", "tags": ["smith", "fill"], "source": "both", "stem": "The toxicologist credited with the phrase \"the dose makes the poison\" is ____.", "answer": "Paracelsus", "accept": ["Paracelsus"], "bank": ["Paracelsus", "Vogel", "Motulsky", "Casarett", "Doull"], "teach": "Dose is the fourth principle of toxicology. She attributed the phrase to Paracelsus, who studied the toxic effects of compounds. The LD50 table she showed, from Casarett and Doull's toxicology book, lists rat LD50s that vary enormously between compounds.", "quote": "Dose makes the poison ... Supposed to be attributed to a guy named Paracelsus", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘Dose’; transcript 10/9"},
{"id": "NEW3-067", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "duration", "skill": "recall", "type": "fill", "concept": "fill-chronic-duration", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her Quiz 1 question 2", "stem": "In animal studies, chronic exposure is repeated exposure for more than ____ months.", "answer": "3", "accept": ["3", "three"], "bank": ["3", "1", "6", "12", "24"], "teach": "Durations in animal studies: acute, less than 24 hours; subacute, less than 1 month; subchronic, 1 to 3 months; chronic, more than 3 months (up to years). Her Quiz 1 question 2 keyed \"More than three months.\"", "quote": "Sub-chronic is 1 to 3 months, and then chronic is more than 3 months up to years", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘Exposure: Duration’; Smith_Practice_Quiz_1_-_Principles_of_Toxicology.pdf question 2; transcript 10/9"},
{"id": "NEW3-068", "lecture": "L13", "prof": "Smith", "tier": "new", "topic": "L13", "sub": "princ", "skill": "recall", "type": "fill", "concept": "fill-target-mechanism", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her Quiz 1 question 10: list the five principles", "stem": "The five principles of toxicology are source, exposure, ADMET, dose, and ____ and mechanism of action.", "answer": "target", "accept": ["target"], "bank": ["target", "receptor", "route", "frequency", "threshold", "tolerance"], "teach": "The five principles: source, exposure, ADMET, dose, target and mechanism of action. Under target and mechanism: the target of a toxic effect may not be the therapeutic target, and the organ with the highest concentration may not be the one damaged.", "quote": "You'll find over time that sometimes the target of something toxic is not the same target as its therapeutic target", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘5 Principles of Toxicology’; Smith_Practice_Quiz_1_-_Principles_of_Toxicology.pdf question 10; transcript 10/9"},
{"id": "NEW3-069", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "indices", "skill": "recall", "type": "fill", "concept": "fill-ti-denominator", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her Quiz 1 question 3 (therapeutic index formula)", "stem": "The therapeutic index is calculated as TD50 / ____.", "answer": "ED50", "accept": ["ED50", "ED 50"], "bank": ["ED50", "ED99", "LD50", "TD1", "NOAEL", "ED1"], "teach": "Therapeutic index = TD50 / ED50: toxic dose in 50% over effective dose in 50%. Another percentage can be used, but numerator and denominator must use the same percentage. Her Quiz 1 question 3 keyed the formula toxic dose / therapeutic dose as the therapeutic index.", "quote": "It doesn't always have to be 50%. It could be a different percentage, but the numerator and the denominator need to have the same percentage", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘Values Developed from Dose-Response’; Smith_Practice_Quiz_1_-_Principles_of_Toxicology.pdf question 3; transcript 10/13"},
{"id": "NEW3-070", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "indices", "skill": "recall", "type": "fill", "concept": "fill-mos-denominator", "tags": ["smith", "fill"], "source": "both", "stem": "The margin of safety is calculated as TD1 / ____, which gives an idea of the slope of the dose–response curve.", "answer": "ED99", "accept": ["ED99", "ED 99"], "bank": ["ED99", "ED50", "LD50", "TD50", "NOAEL", "ED1"], "teach": "Margin of safety = TD1 / ED99: the toxic dose for 1% of the animals over the effective dose for 99%. Because it uses two different percentages, it gives an idea of the slope of the dose–response curve; the therapeutic index does not.", "quote": "what's the toxic dose for 1% of the animals over the effective dose of 99% of the animals. That's the margin of safety.", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘Values Developed from Dose-Response’; transcript 10/13"},
{"id": "NEW3-071", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "indices", "skill": "recall", "type": "fill", "concept": "fill-moe-noael", "tags": ["smith", "fill"], "source": "both", "stem": "The margin of exposure is the ____ divided by the estimated human exposure.", "answer": "NOAEL", "accept": ["NOAEL", "no observed adverse effect level", "no observable adverse effect level"], "bank": ["NOAEL", "ED50", "TD50", "LD50", "ED99", "TD1"], "teach": "Margin of exposure = NOAEL / estimated exposure. It is used for repeated exposures to compounds that are not therapeutic (a pollutant, an occupational exposure). The NOAEL (no observed adverse effect level) comes from animal studies: a dose at which the animals had no adverse response.", "quote": "And so the margin of exposure is defined as the Noel over the chronic exposure.", "cite": "Principles-of-Tox-Lecture-Students-Fall-2026_WCAG21A.pdf slide ‘Values Developed from Dose-Response’; transcript 10/13"},
{"id": "NEW3-072", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "tolerance", "skill": "recall", "type": "fill", "concept": "fill-dispositional-tolerance", "tags": ["smith", "fill"], "source": "both", "stem": "Tolerance from a decreased amount of toxicant reaching the site where the toxic effect is produced is called ____ tolerance.", "answer": "dispositional", "accept": ["dispositional"], "bank": ["dispositional", "selective", "idiosyncratic", "cumulative", "synergistic"], "teach": "Two mechanisms of tolerance: dispositional tolerance (ADME based: less toxicant reaches the site; carbon tetrachloride inhibits its own metabolism, cadmium induces the metal-carrying protein that helps clear it) and reduced responsiveness of the tissue (for example down-regulation of receptors).", "quote": "So there's what we call dispositional tolerance, and then there's what we call reduced responsiveness type of tolerance.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Undesired Effects: general concepts Tolerance’; transcript 10/13"},
{"id": "NEW3-073", "lecture": "L14", "prof": "Smith", "tier": "new", "topic": "L14", "sub": "variation", "skill": "recall", "type": "fill", "concept": "fill-selective-toxicity", "tags": ["smith", "fill"], "source": "both", "stem": "An exposure that is lethal to one species but not to another shows ____ toxicity.", "answer": "selective", "accept": ["selective"], "bank": ["selective", "idiosyncratic", "dispositional", "systemic", "synergistic"], "teach": "Variations in effect: selective toxicity (lethal to one species but not another); species differences (qualitative and quantitative, which raise questions of extrapolating between species); individual differences, due to differences in genetic profile.", "quote": "One of the terms is what we call selective toxicity. This means that an exposure could be lethal to one species, but not to another", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Undesired Effects: general concepts Variations in Effect’; transcript 10/13"},
{"id": "NEW3-074", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "hepat", "skill": "recall", "type": "fill", "concept": "fill-kupffer", "tags": ["smith", "fill"], "source": "both", "stem": "The liver's resident white blood cells are called ____ cells.", "answer": "Kupffer", "accept": ["Kupffer", "Kupffer cells", "Kupfer"], "bank": ["Kupffer", "Schwann", "Hepatic stellate", "Glial", "Mast", "Langerhans"], "teach": "Kupffer cells wait in the liver to clean up damaged tissue and fight pathogens. While doing that they release inflammatory cytokines and reactive oxygen species, which adds to the liver's susceptibility to hepatotoxins. They are found all over the liver, not in one zone.", "quote": "K U P F E R, Coopfer cells ... a kind of white blood cell that resides in the liver, waiting to be called up", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Hepatotoxicity – Why is liver susceptible?’; transcript 10/14"},
{"id": "NEW3-075", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "zones", "skill": "recall", "type": "fill", "concept": "fill-zone3", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her Quiz 2 question 8 and poll 4 (zones, oxygen, CYP2E1)", "stem": "In the acinar model of the liver, ____ is closest to the central venule, where the blood leaves.", "answer": "zone 3", "accept": ["zone 3", "zone three", "3"], "bank": ["zone 3", "zone 1", "zone 2", "the lobule", "the acinus"], "teach": "Zone 1 is closest to the inflow vessels and has the most oxygen; zone 3 is closest to the central venule and is relatively hypoxic; zone 2 is intermediate. CYP2E1 is more highly expressed in zone 3, so acetaminophen kills hepatocytes in zone 3.", "quote": "zone 1 is closest to ... the vessels where the blood comes into the liver, and zone 3 is closest to the vessel where the blood leaves the liver", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Reasons for Site-Specific Hepatotoxicity’; transcript 10/14"},
{"id": "NEW3-076", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "neuro", "skill": "recall", "type": "fill", "concept": "fill-neuronopathy", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her Quiz 2 question 6 (neuronopathy)", "stem": "Neurotoxic injury in which the entire neuron dies is called ____.", "answer": "neuronopathy", "accept": ["neuronopathy"], "bank": ["neuronopathy", "axonopathy", "myelinopathy", "gliosis", "chromatolysis"], "teach": "Patterns of neurotoxic injury: neuronopathy (death of the entire neuron; astrocytes often proliferate, giving gliosis), axonopathy (the axon degenerates; the surviving cell body shows chromatolysis), myelinopathy (disruption of myelin or injury to the myelinating cells), and interruption of neurotransmission.", "quote": "What did that neurotoxin do to this nerve cell? Killed the whole thing", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Types of Neurotoxicity’ (Figure 16-2); transcript 10/14"},
{"id": "NEW3-077", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "neuro", "skill": "recall", "type": "fill", "concept": "fill-schwann", "tags": ["smith", "fill"], "source": "both", "stem": "In the peripheral nervous system, myelin is formed by ____ cells.", "answer": "Schwann", "accept": ["Schwann", "Schwann cells"], "bank": ["Schwann", "oligodendrocyte", "Kupffer", "astrocyte", "endothelial"], "teach": "Myelination begins when a myelinating cell encircles an axon: Schwann cells in the peripheral nervous system, oligodendrocytes in the CNS. Myelin is one reason the nervous system is susceptible; injury to it is myelinopathy, with remyelination much less effective in the CNS than in the PNS.", "quote": "these Schwann cells, they are formed around the axons of nerves ... they get very stretched and they wrap around and around and around the axon.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Susceptibility to Neurotoxicity - Myelin’ (Figure 16-3); transcript 10/14"},
{"id": "NEW3-078", "lecture": "L15", "prof": "Smith", "tier": "new", "topic": "L15", "sub": "nephro", "skill": "recall", "type": "fill", "concept": "fill-ppi-interstitial", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her words 10/14: add the PPIs to the list of drugs that cause interstitial nephritis", "stem": "Proton pump inhibitors such as omeprazole can cause ____ nephritis.", "answer": "interstitial", "accept": ["interstitial", "interstitial nephritis"], "bank": ["interstitial", "glomerular", "tubular", "prerenal", "endothelial"], "teach": "On the renal table, interstitial nephritis is listed for antibiotics, NSAIDs and diuretics; she said to add the PPIs. The over-the-counter PPI label says to limit use to two weeks. Kinds of renal damage: prerenal, vasoconstriction, crystalluria, tubular toxicity, endothelial injury, glomerulopathy, interstitial nephritis.", "quote": "So your proton pump inhibitors, your PPIs, can cause interstitial nephritis.", "cite": "Toxic Responses Students Fall 2026 WCAG21A.pdf slide ‘Toxic Endpoints Specific: Site-Specific Nephrotoxicity’; transcript 10/14"},
{"id": "NEW3-079", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "metab", "skill": "recall", "type": "fill", "concept": "fill-glutathione", "tags": ["smith", "fill"], "source": "both", "stem": "NAPQI, the toxic metabolite of acetaminophen, is conjugated by ____ with the help of the GST enzymes.", "answer": "glutathione", "accept": ["glutathione", "GSH"], "bank": ["glutathione", "N-acetylcysteine", "thiosulfate", "rhodanese", "methemoglobin", "fomepizole"], "teach": "Glutathione conjugates NAPQI with the help of the glutathione S-transferases. The body makes glutathione all the time, but an overdose uses it up; N-acetylcysteine supplies the ingredients to make more (her key: replenishes glutathione). This is enhancing metabolism with a cofactor.", "quote": "what compound grabs NAQI, conjugates it? Glutathione, with the help of the GST enzymes ... you end up conjugating NAQI with glutathione.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Toxicokinetic-Based Treatment Acetaminophen Example’; transcript 10/19"},
{"id": "NEW3-080", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "metab", "skill": "recall", "type": "fill", "concept": "fill-napqi", "tags": ["smith", "fill"], "source": "both", "stem": "The liver-toxic metabolite of acetaminophen is ____.", "answer": "NAPQI", "accept": ["NAPQI", "N-acetyl-p-benzoquinone imine"], "bank": ["NAPQI", "formic acid", "oxalic acid", "glycolic acid", "formaldehyde", "methemoglobin"], "teach": "CYP2E1 bioactivates acetaminophen to NAPQI, which damages the liver (zone 3). Glutathione conjugates it; N-acetylcysteine replenishes glutathione. The other metabolites in the bank belong to the toxic alcohols: methanol to formaldehyde and formic acid; ethylene glycol to glycolic acid and oxalic acid.", "quote": "NAQI, that's that free radical, that's nasty, damages liver.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Toxicokinetic-Based Treatment Acetaminophen Example’; transcript 10/19"},
{"id": "NEW3-081", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "bioact", "skill": "recall", "type": "fill", "concept": "fill-adh", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her key (toxic alcohols mechanism); her Quiz 3 question 1", "stem": "Ethanol and fomepizole treat methanol and ethylene glycol poisoning by inhibiting ____.", "answer": "alcohol dehydrogenase", "accept": ["alcohol dehydrogenase", "ADH"], "bank": ["alcohol dehydrogenase", "aldehyde dehydrogenase", "acetylcholinesterase", "epoxide reductase", "cytochrome c oxidase", "rhodanese"], "teach": "Inhibit bioactivation: methanol and ethylene glycol are bioactivated by alcohol dehydrogenase (methanol to formaldehyde and formic acid; ethylene glycol to glycoaldehyde, glycolic acid and oxalic acid). The antidote for both is ethanol or fomepizole. Her Quiz 3 question 1 keyed fomepizole as inhibition of bioactivation.", "quote": "both of these compounds, we can use ... compounds that will block the activity of the alcohol dehydrogenase enzyme.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slides ‘Toxicokinetic-Based Treatment Inhibit Bioactivation’, ‘methanol and ethylene glycol examples’; PoisoningTreatmentTable2026KEY.pdf row ‘Toxic alcohols’; transcript 10/19"},
{"id": "NEW3-082", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "renal", "skill": "recall", "type": "fill", "concept": "fill-ion-trapping", "tags": ["smith", "fill"], "source": "both", "stem": "Intravenous sodium bicarbonate enhances the renal clearance of weakly acidic poisons such as salicylates by ____.", "answer": "ion trapping", "accept": ["ion trapping", "renal ion trapping"], "bank": ["ion trapping", "chelation", "hemodialysis", "hemoperfusion", "gastric lavage", "whole bowel irrigation"], "teach": "Raising urine pH with sodium bicarbonate leaves the weakly acidic poison charged in the urine, so the tubules do not reabsorb it. Very effective for salicylates and phenobarbital; not done for weakly basic toxins. Her key: salicylates, IV sodium bicarbonate, renal ion trapping to enhance elimination.", "quote": "It's safest to try to treat slightly acidic poisonings by ion trapping, rather than trying to treat slightly basic poisonings by ion trapping", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Toxicokinetic-Based Treatment Enhance Renal Elimination’; PoisoningTreatmentTable2026KEY.pdf row ‘Salicylates’; transcript 10/19"},
{"id": "NEW3-083", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "antibody", "skill": "recall", "type": "fill", "concept": "fill-serum-sickness", "tags": ["smith", "fill"], "source": "both", "stem": "A polyclonal antivenom can cause a type III hypersensitivity reaction called ____.", "answer": "serum sickness", "accept": ["serum sickness"], "bank": ["serum sickness", "anaphylaxis", "withdrawal", "aging", "methemoglobinemia"], "teach": "Antivenoms are antibodies against a venom, made by inoculating animals with small amounts of venom to get a humoral antibody response. They have high affinity and specificity; the danger is a type III hypersensitivity reaction, serum sickness. Example on the slide: digoxin immune Fab.", "quote": "certain kind of hypersensitivity reaction called type 3 hypersensitivity ... that's also called serum sickness.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Inactivation of Poisons: Antivenoms and Antibodies’; transcript 10/19"},
{"id": "NEW3-084", "lecture": "L16", "prof": "Smith", "tier": "new", "topic": "L16", "sub": "pharmsite", "skill": "recall", "type": "fill", "concept": "fill-aging", "tags": ["smith", "fill"], "source": "both", "stem": "When part of an organophosphate breaks off after it binds acetylcholinesterase, the enzyme is permanently bound and pralidoxime cannot remove it. This is called ____.", "answer": "aging", "accept": ["aging", "ageing"], "bank": ["aging", "chelation", "bioactivation", "ion trapping", "conjugation"], "teach": "Pralidoxime removes the toxin from the active site, pulling the organophosphate off acetylcholinesterase. If the organophosphate's structure lets a part fall off, the enzyme is permanently bound; that is aging, and pralidoxime no longer works. Atropine still antagonizes the excess acetylcholine at muscarinic receptors.", "quote": "That's called aging of your organophosphate.", "cite": "Treating Poisonings Students Fall 2026 WCAG2,1A_pptx.pdf slide ‘Pharmacological Treatment Pralidoxime example’; transcript 10/19"},
{"id": "NEW3-085", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "metabolic", "skill": "recall", "type": "fill", "concept": "fill-nac-8h", "tags": ["smith", "fill"], "source": "slide", "core": true, "coreWhy": "Her key's special considerations (acetaminophen)", "stem": "N-acetylcysteine loses effectiveness about ____ hours after an acetaminophen overdose, but it should still be given past that point.", "answer": "8", "accept": ["8", "eight"], "bank": ["8", "6", "18", "24", "12", "2"], "teach": "Her key, acetaminophen row: \"At what time after OD does the antidote lose effectiveness? About 8 hours after overdose. Should you still give it past that time point? Yes.\" NAC replenishes glutathione.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Acetaminophen’, special considerations; transcript 10/20"},
{"id": "NEW3-086", "lecture": "TBL3", "prof": "Smith", "tier": "new", "topic": "TBL3", "sub": "cardio", "skill": "recall", "type": "fill", "concept": "fill-lipid-sink", "tags": ["smith", "fill"], "source": "slide", "stem": "In beta-blocker overdose, intravenous 20% fatty acid emulsion acts as a ____ for the drug if the drug is lipophilic enough.", "answer": "sink", "accept": ["sink"], "bank": ["sink", "chelator", "cofactor", "antagonist", "antibody"], "teach": "Her key's beta-blocker mechanisms: atropine, increase heart rate; calcium, try to drive calcium into cardiac cells; glucagon, increase cardiac cellular cAMP to increase heart rate; HIET, mechanisms of inotropic effects not understood; vasopressors, increase blood pressure; IV 20% fatty acid emulsion, acts as a sink for the drug if the drug is lipophilic enough. The same list applies to calcium channel blockers.", "cite": "PoisoningTreatmentTable2026KEY.pdf row ‘Beta blockers’, mechanism of action; transcript 10/20"},
{"id": "NEW3-087", "lecture": "GRG3", "prof": "Smith", "tier": "new", "topic": "GRG3", "sub": "both", "skill": "recall", "type": "fill", "concept": "fill-ir-6h", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her words 10/19: know those time frames", "stem": "An asymptomatic patient who took an immediate-release calcium channel blocker and is found within ____ hours of ingestion should be taken to a hospital.", "answer": "6", "accept": ["6", "six"], "bank": ["6", "8", "18", "24", "12", "2"], "teach": "Immediate release (calcium channel blockers, and beta blockers except sotalol): within 6 hours, get them to a hospital; after 6 hours, call the Poison Center, and they can probably be managed at home. Immediate-release products are absorbed more rapidly because they won't tend to form bezoars.", "quote": "What do you do for a patient that's asymptomatic and they've ingested an immediate release product, and you found them within 6 hours of ingestion. And this question is good for both your calcium channel blockers and your beta blockers", "cite": "Readingguideforoutofhospitalguidelines2026KEY.docx, question 2, both columns; transcript 10/19"},
{"id": "NEW3-088", "lecture": "GRG3", "prof": "Smith", "tier": "new", "topic": "GRG3", "sub": "bb", "skill": "recall", "type": "fill", "concept": "fill-sr-bb-8h", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her words 10/19: know those time frames", "stem": "An asymptomatic patient who took a sustained-release beta blocker and is found within ____ hours of ingestion should be taken to a hospital.", "answer": "8", "accept": ["8", "eight"], "bank": ["8", "6", "18", "24", "12", "2"], "teach": "Sustained-release beta blocker: within 8 hours, get them to a hospital; after 8 hours, call the Poison Center. Extended-release products tend to form bezoars that may break apart at unpredictable times.", "quote": "Same thing with the beta blockers, a sustained release product ... but the time frame for this is within 8 hours ... You got to get him to the hospital.", "cite": "Readingguideforoutofhospitalguidelines2026KEY.docx, Beta Blockers, question 2; transcript 10/19"},
{"id": "NEW3-089", "lecture": "GRG3", "prof": "Smith", "tier": "new", "topic": "GRG3", "sub": "ccb", "skill": "recall", "type": "fill", "concept": "fill-mr-ccb-18h", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her words 10/19: know those time frames", "stem": "An asymptomatic patient who took a modified-release calcium channel blocker other than verapamil and is found within ____ hours of ingestion should be taken to a hospital.", "answer": "18", "accept": ["18", "eighteen"], "bank": ["18", "6", "8", "24", "12", "2"], "teach": "Modified-release calcium channel blocker, except verapamil: within 18 hours, get them to a hospital; after 18 hours, call the Poison Center, and they can probably be managed at home.", "quote": "they're asymptomatic, and they ingested the modified release product, and you found them within 18 hours of ingestion. You need to get him in.", "cite": "Readingguideforoutofhospitalguidelines2026KEY.docx, Calcium Channel Blockers, question 2; transcript 10/19"},
{"id": "NEW3-090", "lecture": "GRG3", "prof": "Smith", "tier": "new", "topic": "GRG3", "sub": "ccb", "skill": "recall", "type": "fill", "concept": "fill-mr-verapamil-24h", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her words 10/19 and 10/20: know those time frames, verapamil differs", "stem": "An asymptomatic patient who took modified-release verapamil and is found within ____ hours of ingestion should be taken to a hospital.", "answer": "24", "accept": ["24", "twenty-four"], "bank": ["24", "6", "8", "18", "12", "2"], "teach": "Modified-release verapamil: within 24 hours, get them to a hospital; after 24 hours, call the Poison Center. On 10/20 she said verapamil is not as clean a calcium channel blocker as the others.", "quote": "If you found a person that's ingested modified release verapamil, and you found them within 24 hours of ingestion. You still get them to the hospital", "cite": "Readingguideforoutofhospitalguidelines2026KEY.docx, Calcium Channel Blockers, question 2; transcript 10/19"},
{"id": "NEW3-091", "lecture": "L17", "prof": "Smith", "tier": "new", "topic": "L17", "sub": "haplo", "skill": "recall", "type": "fill", "concept": "fill-haplotype", "tags": ["smith", "fill"], "source": "both", "stem": "A set of alleles at multiple loci that co-exist on the same chromosome is a ____.", "answer": "haplotype", "accept": ["haplotype"], "bank": ["haplotype", "genotype", "phenotype", "allele", "polymorphism", "SNP"], "teach": "Haplotype: a set of alleles at multiple loci or areas of a gene that co-exist on the same chromosome. When the set co-exists more often than random chance predicts, that is linkage disequilibrium. A genotype is the two alleles a person carries for a gene.", "quote": "haplotype, it just means it's a set of alleles at multiple loci that coexist in the same chromosome.", "cite": "Intro_to_PGx_Lecture_Students_Fall_2026.pdf slide ‘Haplotype’ (p. 19); transcript 10/20"},
{"id": "NEW3-092", "lecture": "L17", "prof": "Smith", "tier": "new", "topic": "L17", "sub": "variant", "skill": "recall", "type": "fill", "concept": "fill-polymorphism-1pct", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her words 10/20: every slide with a term on it, you need to know those terms", "stem": "A genetic variation present in at least ____% of a population is a genetic polymorphism.", "answer": "1", "accept": ["1", "one"], "bank": ["1", "5", "10", "50", "99"], "teach": "Polymorphism: a variation in DNA sequence present in at least 1% of the population; less than 1% is a rare variant. Any kind of variation (a single nucleotide, several nucleotides, a whole gene inserted, deleted or copied) counts if it reaches 1%.", "quote": "if you find a genetic variant ... and it's occurring in at least 1% of your population, it's a polymorphism", "cite": "Intro_to_PGx_Lecture_Students_Fall_2026.pdf slide ‘Polymorphism’ (p. 14); transcript 10/20"},
{"id": "NEW3-093", "lecture": "L17", "prof": "Smith", "tier": "new", "topic": "L17", "sub": "haplo", "skill": "recall", "type": "fill", "concept": "fill-linkage-disequilibrium", "tags": ["smith", "fill"], "source": "slide", "stem": "Alleles at different loci that co-exist on a chromosome more often than random chance would predict are said to be in ____.", "answer": "linkage disequilibrium", "accept": ["linkage disequilibrium"], "bank": ["linkage disequilibrium", "Hardy-Weinberg equilibrium", "heterozygosity", "homozygosity", "genotype frequency"], "teach": "The Haplotype slide (p. 19): a higher frequency of the set of alleles co-existing than random chance predicts is linkage disequilibrium. Hardy-Weinberg equilibrium is different: allele and genotype frequencies stay constant from generation to generation unless specific influences are introduced.", "note": "She described the greater-than-chance frequency as the haplotype's statistical significance and did not say the words linkage disequilibrium; the term is on the slide. Her Quiz 4 Q9 key folds the higher-than-chance frequency into the definition of a haplotype, so the stem asks for the state the alleles are in, which only linkage disequilibrium names.", "cite": "Intro_to_PGx_Lecture_Students_Fall_2026.pdf slide ‘Haplotype’ (p. 19)"},
{"id": "NEW3-094", "lecture": "L17", "prof": "Smith", "tier": "new", "topic": "L17", "sub": "allele", "skill": "recall", "type": "fill", "concept": "fill-heterozygous", "tags": ["smith", "fill"], "source": "both", "core": true, "coreWhy": "Her words 10/20: get hung up on the terms homozygosity and heterozygosity", "stem": "A person who carries two different alleles at a locus is ____ at that locus.", "answer": "heterozygous", "accept": ["heterozygous"], "bank": ["heterozygous", "homozygous", "haploid", "diploid", "polymorphic", "wild type"], "teach": "Humans are diploid: two copies of each chromosome, one allele from the biological mother and one from the biological father. Two identical alleles at a locus: homozygous. Two different alleles: heterozygous. In the figure, the person with big B on one chromosome and little b on the other is heterozygous at the third locus.", "quote": "homozygous or heterozygous. They're heterozygous", "cite": "Intro_to_PGx_Lecture_Students_Fall_2026.pdf slides ‘Allele’ (p. 15), ‘Homozygosity and Heterozygosity’ (p. 16); transcript 10/20"}
);
